import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../utils/authContext';
import { Card, Tag, Button, Modal, Input, message, Empty, Spin } from 'antd';
import { CheckCircleOutlined, CloseCircleOutlined, HistoryOutlined, EyeOutlined, EditOutlined, CheckOutlined, CloseOutlined } from '@ant-design/icons';
import { formatMoney } from '../utils/calculations';
import { parseFY, FYSelector } from '../utils/fiscalYear';
import { approvalService } from '../services/approvalService';
import { quotationService } from '../services/quotationService';
import { deliveryService } from '../services/deliveryService';
import type { ApprovalRequest, ReviewRecord } from '../types';
import { COLORS } from '../styles/colors';

const statusConfig: Record<string, { label: string; color: string }> = {
  pending:  { label: '待审批', color: COLORS.warning },
  approved: { label: '已通过', color: COLORS.success },
  rejected: { label: '已驳回', color: COLORS.danger },
};

const typeColor = (t: string) => t === 'quotation' ? COLORS.primary : t === 'plan' ? COLORS.warning : t === 'cost' ? COLORS.success : COLORS.purple;

const ApprovalList: React.FC = () => {
  const navigate = useNavigate();
  const [msg, ctx] = message.useMessage();
  const [requests, setRequests] = useState<ApprovalRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const [draftQuotes, setDraftQuotes] = useState<any[]>([]);
  const [draftDeliveries, setDraftDeliveries] = useState<any[]>([]);

  const loadApprovals = useCallback(async () => {
    try {
      const data = await approvalService.list();
      setRequests(data || []);
    } catch {
      setRequests([]);
    } finally {
      setLoading(false);
    }
    // 并行加载草稿数据
    quotationService.list().then(data => {
      setDraftQuotes(data?.filter((q: any) => q.status === 'draft') || []);
    }).catch(() => {});
    deliveryService.list().then(data => {
      setDraftDeliveries(data?.filter((p: any) => p.planStatus === 'draft' || p.costStatus === 'draft') || []);
    }).catch(() => {});
  }, []);

  useEffect(() => {
    loadApprovals();
  }, [loadApprovals]);

  const defaultFy = `FY${String(new Date().getFullYear() % 100).padStart(2,'0')}${String((new Date().getFullYear() + 1) % 100).padStart(2,'0')}`;
  const { user } = useAuth();
  const [filter, setFilter] = useState<'draft' | 'pending' | 'done' | 'all' | 'mine'>('pending');
  const [fySelect, setFySelect] = useState(defaultFy);
  const [searchText, setSearchText] = useState('');
  const [detailModal, setDetailModal] = useState<ApprovalRequest | null>(null);
  const [draftDetail, setDraftDetail] = useState<any | null>(null);
  const [historyModal, setHistoryModal] = useState<ApprovalRequest | null>(null);
  const [historyRecords, setHistoryRecords] = useState<ReviewRecord[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  const filtered = useMemo(() => {
    let items = requests;
    if (filter === 'pending') items = items.filter(r => r.status === 'pending');
    if (filter === 'done') items = items.filter(r => r.status !== 'pending');
    if (filter === 'mine') items = items.filter(r => r.submitter === user?.displayName);
    // 财年过滤
    const fyRange = parseFY(fySelect);
    if (fyRange.start <= new Date()) {
      items = items.filter(r => {
        const d = r.submitTime ? new Date(r.submitTime) : null;
        return d && d >= fyRange.start && d <= fyRange.end;
      });
    }
    // 搜索过滤
    if (searchText.trim()) {
      const q = searchText.trim().toLowerCase();
      items = items.filter(r => (r.salesNo || '').toLowerCase().includes(q) || (r.clientName || '').toLowerCase().includes(q));
    }
    return items;
  }, [requests, filter, fySelect, searchText, user]);

  const draftItems = useMemo(() => {
    const items: any[] = [];
    for (const q of draftQuotes) {
      items.push({ id: 'dq-' + q.id, approvalType: 'quotation', clientName: q.clientName, projectName: q.projectName, salesNo: q.salesNo, amount: q.amount, submitter: user?.displayName || '方案经理', quotationId: q.id });
    }
    for (const p of draftDeliveries) {
      if (p.planStatus === 'draft') items.push({ id: 'dp-' + p.id, approvalType: 'plan', clientName: p.clientName, projectName: p.projectName, salesNo: p.salesNo, amount: p.contractAmount, submitter: user?.displayName || '方案经理', deliveryId: p.id, quotationId: p.quotationId });
      if (p.costStatus === 'draft') items.push({ id: 'dc-' + p.id, approvalType: 'cost', clientName: p.clientName, projectName: p.projectName, salesNo: p.salesNo, amount: p.contractAmount, submitter: user?.displayName || '提交人', deliveryId: p.id, quotationId: p.quotationId });
    }
    // 搜索过滤（与已审批/全部标签统一规则）
    if (searchText.trim()) {
      const q = searchText.trim().toLowerCase();
      return items.filter(r => (r.salesNo || '').toLowerCase().includes(q) || (r.clientName || '').toLowerCase().includes(q));
    }
    return items;
  }, [draftQuotes, draftDeliveries, user, searchText]);

  const [approvalModal, setApprovalModal] = useState<{ req: ApprovalRequest; action: 'approved' | 'rejected' } | null>(null);
  const [approvalComment, setApprovalComment] = useState('');

  const handleApprove = useCallback((req: ApprovalRequest) => {
    setApprovalModal({ req, action: 'approved' });
    setApprovalComment('');
  }, []);

  const handleReject = useCallback((req: ApprovalRequest) => {
    setApprovalModal({ req, action: 'rejected' });
    setApprovalComment('');
  }, []);

  const [approving, setApproving] = useState(false);
  const confirmApproval = useCallback(async () => {
    const modal = approvalModal;
    if (!modal || approving) return;
    if (modal.action === 'rejected' && !approvalComment.trim()) {
      msg.warning('驳回必须填写原因');
      return;
    }
    setApproving(true);
    try {
      await approvalService.addRecord(modal.req.id, {
        reviewer: user?.displayName || '刘总监',
        action: modal.action,
        comment: approvalComment || undefined,
      });
      await loadApprovals();
      setApprovalModal(null);
      setApprovalComment('');
      if (modal.action === 'approved') msg.success('已通过');
      else msg.warning('已驳回');
    } catch {
      msg.error('操作失败，请重试');
    } finally {
      setApproving(false);
    }
  }, [approvalModal, approvalComment, msg, loadApprovals, approving]);

    return (
    <div>
      {ctx}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <span style={{ fontSize: 17, fontWeight: 700, color: COLORS.textDark }}>审批管理</span>
        <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
          <table style={{ borderCollapse: 'collapse' }}><tbody><tr>
            <td style={{ padding: '6px 12px', fontSize: 12, border: `1px solid ${COLORS.border}`, verticalAlign: 'middle' }}>
              <input placeholder="搜索客户/销售号" value={searchText} onChange={e => setSearchText(e.target.value)}
                style={{ width: 180, border: 'none', background: 'transparent', outline: 'none', fontSize: 12, padding: 0, margin: 0, display: 'block', boxSizing: 'border-box' }} />
            </td>
          </tr></tbody></table>
          <FYSelector value={fySelect} onChange={setFySelect} />
        </div>
      </div>

      <div style={{ display: 'flex', gap: 0, marginTop: 20, marginBottom: 20, borderBottom: `2px solid ${COLORS.border}` }}>
        <div onClick={() => setFilter('draft')}
          style={{ padding: '8px 20px', cursor: 'pointer', fontSize: 14, borderBottom: filter === 'draft' ? `2px solid ${COLORS.textLight}` : '2px solid transparent', color: filter === 'draft' ? COLORS.textLight : COLORS.textSecondary, fontWeight: filter === 'draft' ? 600 : 400, marginBottom: -2, transition: 'all 0.15s' }}>草稿({draftItems.length})</div>
        <div onClick={() => setFilter('pending')}
          style={{
            padding: '8px 20px', cursor: 'pointer', fontSize: 14,
            borderBottom: filter === 'pending' ? `2px solid ${COLORS.warning}` : '2px solid transparent',
            color: filter === 'pending' ? COLORS.warning : COLORS.textSecondary, fontWeight: filter === 'pending' ? 600 : 400,
            marginBottom: -2, transition: 'all 0.15s',
          }}>待审批({requests.filter(r => r.status === 'pending').length})
        </div>
        <div onClick={() => setFilter('done')}
          style={{
            padding: '8px 20px', cursor: 'pointer', fontSize: 14,
            borderBottom: filter === 'done' ? `2px solid ${COLORS.success}` : '2px solid transparent',
            color: filter === 'done' ? COLORS.success : COLORS.textSecondary, fontWeight: filter === 'done' ? 600 : 400,
            marginBottom: -2, transition: 'all 0.15s',
          }}>已审批({requests.filter(r => r.status !== 'pending').length})
        </div>
        <div onClick={() => setFilter('mine')}
          style={{
            padding: '8px 20px', cursor: 'pointer', fontSize: 14,
            borderBottom: filter === 'mine' ? `2px solid ${COLORS.purple}` : '2px solid transparent',
            color: filter === 'mine' ? COLORS.purple : COLORS.textSecondary, fontWeight: filter === 'mine' ? 600 : 400,
            marginBottom: -2, transition: 'all 0.15s',
          }}>我提交的({requests.filter(r => r.submitter === user?.displayName).length})
        </div>
        <div onClick={() => setFilter('all')}
          style={{
            padding: '8px 20px', cursor: 'pointer', fontSize: 14,
            borderBottom: filter === 'all' ? `2px solid ${COLORS.primary}` : '2px solid transparent',
            color: filter === 'all' ? COLORS.primary : COLORS.textSecondary, fontWeight: filter === 'all' ? 600 : 400,
            marginBottom: -2, transition: 'all 0.15s',
          }}>全部({requests.length})
        </div>
      </div>

      {filter === 'draft' && draftItems.length === 0 && (
        <Empty description="暂无草稿内容" style={{ padding: 40, background: '#fff', borderRadius: 6 }} />
      )}
      {filter === 'draft' && draftItems.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {draftItems.map(item => (
            <Card key={item.id} size="small" style={{ borderRadius: 4, borderLeft: '4px solid ' + typeColor(item.approvalType) }}>
              <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                    <span style={{ fontSize: 15, fontWeight: 600, color: COLORS.textDark }}>{item.clientName}</span>

                    <Tag color={typeColor(item.approvalType)}
                      style={{ fontSize: 12, border: 'none', fontWeight: 600 }}>
                      {item.approvalType === 'quotation' ? '报价审批' : item.approvalType === 'plan' ? '实施计划' : item.approvalType === 'cost' ? '成本对比' : '转机会审批'}
                    </Tag>
                  </div>
                  <div style={{ display: 'flex', gap: 24, fontSize: 13, color: COLORS.textSecondary, flexWrap: 'wrap' }}>
                    <span style={{ fontWeight: 600 }}>{item.projectName}</span>
                    <span>{item.salesNo}</span>
                    <span><strong style={{ color: COLORS.primary }}>&yen;{formatMoney(item.amount)}</strong></span>
                  </div>
                  <div style={{ marginTop: 4, fontSize: 12, color: COLORS.textLight }}>
                    {item.submitter}@未提交
                  </div>
                </div>
                <div style={{ display: 'flex', gap: 16, alignItems: 'center', marginLeft: 16, flexShrink: 0 }}>
                  <Button type="text" size="small" icon={<EyeOutlined style={{ fontSize: 18 }} />}
                    onClick={() => setDraftDetail(item)}
                    style={{ color: COLORS.primary }} title="查看详情" />
                  <Button type="text" size="small" icon={<EditOutlined style={{ fontSize: 18 }} />}
                    onClick={() => item.approvalType === 'promote' ? navigate('/opportunities?tab=' + (item.status === 'approved' ? 'opp' : 'lead')) : item.deliveryId ? navigate('/delivery/' + item.deliveryId, { state: { tab: item.approvalType === 'cost' ? 'cost' : 'plan' } }) : navigate('/quotations/' + item.quotationId)}
                    style={{ color: COLORS.primary }} title="跳转编辑" />
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
      {filter !== 'draft' && loading && (
        <div style={{ textAlign: 'center', padding: 60 }}><Spin size="large" /></div>
      )}
      {filter !== 'draft' && !loading && filtered.length === 0 && (
        <Empty description="暂无审批记录" style={{ padding: 40, background: '#fff', borderRadius: 6 }} />
      )}
      {filter !== 'draft' && !loading && filtered.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {filtered.map(req => (
            <Card
              key={req.id}
              size="small"
              style={{
                borderRadius: 4,
                borderLeft: `4px solid ${
                  req.status === 'pending' ? COLORS.warning :
                  req.status === 'approved' ? COLORS.success : COLORS.danger
                }`,
              }}
            >
              <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                    <span style={{ fontSize: 15, fontWeight: 600, color: COLORS.textDark }}>{req.clientName}</span>
                    <span style={{ fontSize: 13, color: COLORS.textSecondary }}>{req.salesNo}</span>
                    <span style={{ fontSize: 13, color: COLORS.textSecondary }}>{(req as any).versionNo || 'V1.0'}</span>
                    <Tag color={typeColor(req.approvalType)} style={{ fontSize: 12, border: 'none', fontWeight: 600 }}>{req.approvalType === 'quotation' ? '报价审批' : req.approvalType === 'plan' ? '实施计划' : req.approvalType === 'cost' ? '成本对比' : '转机会审批'}</Tag>
                    {req.status !== 'pending' && <Tag color={statusConfig[req.status]?.color} style={{ fontWeight: 600, fontSize: 12, lineHeight: '20px', borderRadius: 3 }}>{statusConfig[req.status]?.label}</Tag>}
                  </div>
                  <div style={{ display: 'flex', gap: 24, fontSize: 13, color: COLORS.textSecondary, flexWrap: 'wrap' }}>
                    <span style={{ fontWeight: 600 }}>{req.projectName}</span>
                    <span><strong style={{ color: COLORS.primary }}>&yen;{formatMoney(Math.round((req as any).totalAccountingPrice))}</strong></span>
                    <span><strong>&yen;{formatMoney(Math.round(req.amount))}</strong>
                      {(() => { const tap = (req as any).totalAccountingPrice || req.amount; const diff = req.amount - tap; return Math.abs(diff) > 1 ? <span style={{ fontSize: 11, color: COLORS.textLight, marginLeft: 4 }}>({(diff / tap * 100).toFixed(1)}%)</span> : null; })()}
                    </span>
                    <span><strong style={{ color: COLORS.success }}>&yen;{formatMoney(Math.round(req.amount - req.totalCost * (1 + ((req as any).taxRate || 0.13))))}</strong>
                      <span style={{ fontSize: 11, color: COLORS.success, marginLeft: 2 }}>({(req.gp3 * 100).toFixed(1)}%)</span>
                    </span>
                  </div>
                  <div style={{ marginTop: 4, fontSize: 12, color: COLORS.textLight }}>
                    {req.submitter}@{(() => { if (!req.submitTime) return ''; const t = new Date(req.submitTime).getTime() + 8 * 3600 * 1000; return new Date(t).toISOString().replace('T', ' ').slice(0, 19); })()}
                    {(req.records||[]).length > 0 && (
                      <span> | {(req.records||[])[(req.records||[]).length - 1].reviewer}@{(() => { const r = (req.records||[])[(req.records||[]).length - 1]; if (!r || !r.createdAt) return ''; const t = new Date(r.createdAt).getTime() + 8 * 3600 * 1000; return new Date(t).toISOString().replace('T', ' ').slice(0, 19); })()}</span>
                    )}
                    {(() => { const lr = (req as any).latestRecord; if (!lr || !lr.comment) return null; return <div style={{ marginTop: 4, fontSize: 12, color: lr.action === 'approved' ? COLORS.success : COLORS.danger }}>理由：{lr.comment}</div>; })()}
                  </div>
                </div>

                <div style={{ display: 'flex', gap: 16, alignItems: 'center', marginLeft: 16, flexShrink: 0 }}>
                  <Button type="text" size="small" icon={<EyeOutlined style={{ fontSize: 18 }} />}
                    onClick={() => req.approvalType === 'promote' ? navigate('/opportunities?tab=' + (req.status === 'approved' ? 'opp' : 'lead')) : req.deliveryId ? navigate('/delivery/' + req.deliveryId, { state: { tab: req.approvalType === 'cost' ? 'cost' : 'plan' } }) : navigate('/quotations/' + req.quotationId)}
                    style={{ color: COLORS.primary }} />
                  {((req.records||[]).length > 0 || ((req as any).latestRecord || req.status !== 'pending')) && (
                    <Button type="text" size="small" icon={<HistoryOutlined />}
                      onClick={async () => {
                        setHistoryModal(req);
                        setHistoryLoading(true);
                        setHistoryRecords([]);
                        try {
                          // 获取当前审批的完整记录
                          const detail = await approvalService.getDetail(req.id);
                          let allRecords: ReviewRecord[] = [...(detail.records || [])];
                          // 获取同一销售编号 + 同一审批类型 + 不晚于当前提交时间的记录
                          try {
                            const all = await approvalService.list();
                            const related = all.filter(a =>
                              a.id !== req.id &&
                              a.salesNo === req.salesNo &&
                              a.approvalType === req.approvalType &&
                              a.submitTime && req.submitTime &&
                              new Date(a.submitTime) <= new Date(req.submitTime)
                            );
                            for (const other of related) {
                              const od = await approvalService.getDetail(other.id);
                              if (od.records) allRecords = allRecords.concat(od.records);
                            }
                          } catch {}
                          // 按时间降序排列（最新在前）
                          allRecords.sort((a, b) =>
                            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
                          );
                          setHistoryRecords(allRecords);
                        } catch { setHistoryRecords([]); }
                        finally { setHistoryLoading(false); }
                      }}
                      style={{ color: COLORS.textSecondary }} />
                  )}
                  {req.status === 'pending' && (
                    <>
                      <Button type="text" size="small" icon={<CheckCircleOutlined style={{ fontSize: 18 }} />}
                        onClick={() => handleApprove(req)}
                        style={{ color: COLORS.success }} />
                      <Button type="text" size="small" icon={<CloseCircleOutlined style={{ fontSize: 18 }} />}
                        onClick={() => handleReject(req)}
                        style={{ color: COLORS.danger }} />
                    </>
                  )}
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}

      {/* 审批操作弹窗 */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>{approvalModal?.action === 'approved' ? '确认通过' : '确认驳回'}</span>}
        open={!!approvalModal}
        onCancel={() => setApprovalModal(null)}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: '14px 2px 6px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setApprovalModal(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={confirmApproval} loading={approving}
              style={{ borderColor: approvalModal?.action === 'approved' ? COLORS.success : COLORS.danger, color: approvalModal?.action === 'approved' ? COLORS.success : COLORS.danger, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        {approvalModal && (
          <div style={{ padding: '4px 0 0' }}>
            <div style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 12, lineHeight: 1.6 }}>
              项目：<strong style={{ color: COLORS.textPrimary }}>{approvalModal.req.projectName}</strong>
            </div>
            <div style={{ fontWeight: 600, fontSize: 13, color: approvalModal.action === 'approved' ? COLORS.textPrimary : COLORS.danger, marginBottom: 6 }}>
              {approvalModal.action === 'approved' ? '审批意见' : '驳回原因 *'}
            </div>
            <Input.TextArea rows={3}
              placeholder={approvalModal.action === 'approved' ? '输入审批意见（可选）…' : '请输入驳回原因…'}
              value={approvalComment}
              onChange={e => setApprovalComment(e.target.value)}
              style={{ borderRadius: 6, fontSize: 13 }}
            />
          </div>
        )}
      </Modal>

      {/* 草稿详情 Modal */}
      <Modal title="草稿详情" open={!!draftDetail} onCancel={() => setDraftDetail(null)} footer={null} width={460}>
        {draftDetail && (
          <div style={{ fontSize: 13 }}>
            <div style={detailRow}><span style={detailLabel}>客户</span><span>{draftDetail.clientName}</span></div>
            <div style={detailRow}><span style={detailLabel}>项目</span><span>{draftDetail.projectName}</span></div>
            <div style={detailRow}><span style={detailLabel}>销售编号</span><span>{draftDetail.salesNo}</span></div>
            <div style={detailRow}><span style={detailLabel}>金额</span><span>&yen;{formatMoney(draftDetail.amount)}</span></div>
            <div style={detailRow}><span style={detailLabel}>类型</span><span>{draftDetail.approvalType === 'quotation' ? '报价' : draftDetail.approvalType === 'plan' ? '实施计划' : draftDetail.approvalType === 'cost' ? '成本对比' : '转机会'}</span></div>
            <div style={detailRow}><span style={detailLabel}>提交人</span><span>{draftDetail.submitter}</span></div>
            <div style={{ marginTop: 16, color: COLORS.textLight, fontSize: 12 }}>此项目尚未提交审批，可点击编辑图标继续完善。</div>
          </div>
        )}
      </Modal>

      {/* 详情 Modal */}
      <Modal title="项目详情" open={!!detailModal} onCancel={() => setDetailModal(null)} footer={null} width={480}>
        {detailModal && (
          <div style={{ fontSize: 13 }}>
            <div style={detailRow}><span style={detailLabel}>客户</span><span>{detailModal.clientName}</span></div>
            <div style={detailRow}><span style={detailLabel}>项目</span><span>{detailModal.projectName}</span></div>
            <div style={detailRow}><span style={detailLabel}>销售编号</span><span>{detailModal.salesNo}</span></div>
            <div style={detailRow}><span style={detailLabel}>报价金额</span><span>&yen;{formatMoney(detailModal.amount)}</span></div>
            <div style={detailRow}><span style={detailLabel}>总成本</span><span>&yen;{formatMoney(detailModal.totalCost)}</span></div>
            <div style={detailRow}><span style={detailLabel}>GP1</span><span><Gauge value={detailModal.profitRate} />%</span></div>
            <div style={detailRow}><span style={detailLabel}>GP3</span><span><Gauge value={detailModal.gp3 * 100} />%</span></div>
            <div style={detailRow}><span style={detailLabel}>提交人</span><span>{detailModal.submitter}</span></div>
            <div style={detailRow}><span style={detailLabel}>提交时间</span><span>{detailModal.submitTime}</span></div>
          </div>
        )}
      </Modal>

      {/* 审批历史 Modal */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>审批记录</span>}
        open={!!historyModal}
        onCancel={() => { setHistoryModal(null); setHistoryRecords([]); }}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: '14px 2px 6px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setHistoryModal(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }>
        {historyLoading ? (
          <div style={{ textAlign: 'center', color: COLORS.textLight, padding: 20 }}>加载中…</div>
        ) : historyRecords.length > 0 ? (
          <div style={{ position: 'relative', paddingLeft: 24 }}>
            <div style={{ position: 'absolute', left: 11, top: 4, bottom: 4, width: 2, background: COLORS.border }} />
            {historyRecords.map(rec => (
              <div key={rec.id} style={{ position: 'relative', paddingBottom: 16 }}>
                <div style={{
                  position: 'absolute', left: -20, top: 4, width: 12, height: 12, borderRadius: '50%',
                  background: rec.action === 'approved' ? COLORS.success : COLORS.danger,
                  border: '2px solid #fff',
                }} />
                <div style={{ fontSize: 13, color: COLORS.textDark, fontWeight: 600 }}>
                  {rec.action === 'approved' ? '✓ 通过' : '✗ 驳回'} — {rec.reviewer}
                </div>
                <div style={{ fontSize: 12, color: COLORS.textLight }}>
                  {(() => { if (!rec.createdAt) return ''; const t = new Date(rec.createdAt).getTime() + 8 * 3600 * 1000; return new Date(t).toISOString().replace('T', ' ').slice(0, 19); })()}
                </div>
                {historyModal?.versionNo && (
                  <div style={{ fontSize: 12, color: COLORS.textSecondary, marginTop: 2 }}>
                    版本 {historyModal.versionNo}
                  </div>
                )}
                {rec.comment && <div style={{ fontSize: 13, color: COLORS.textSecondary, marginTop: 4 }}>{rec.comment}</div>}
              </div>
            ))}
          </div>
        ) : (
          <div style={{ textAlign: 'center', color: COLORS.textLight, padding: 20 }}>暂无审批记录</div>
        )}
      </Modal>
    </div>
  );
};

const Gauge: React.FC<{ value: number }> = ({ value }) => {
  const num = Number(value);
  const color = num >= 20 ? COLORS.success : num >= 15 ? COLORS.amber : COLORS.danger;
  return <span style={{ fontWeight: 600, color }}>{num.toFixed(1)}</span>;
};

const detailRow: React.CSSProperties = {
  display: 'flex', justifyContent: 'space-between', padding: '6px 0',
  borderBottom: `1px solid ${COLORS.borderLight}`,
};
const detailLabel: React.CSSProperties = {
  fontWeight: 600, color: COLORS.textSecondary, minWidth: 80,
};

export default ApprovalList;

