import React, { useMemo, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, Tag } from 'antd';
import {
  RightOutlined, TrophyOutlined, ClockCircleOutlined,
} from '@ant-design/icons';
import { opportunityService } from '../services/opportunityService';
import { approvalService } from '../services/approvalService';
import { deliveryService } from '../services/deliveryService';
import { clientService } from '../services/clientService';
import { quotationService } from '../services/quotationService';
import type { SalesOpportunity, ApprovalRequest, DeliveryProject, Client, QuotationSummary } from '../types';
import { parseFY } from '../utils/parseFY';
import { COLORS } from '../styles/colors';

const fmtK = (v: number) => Math.round(v / 1000).toLocaleString() + 'K';

/* ── KPI 卡片（与销售分析完全一致） ── */
const KpiCard: React.FC<{
  label: string; value: string; color: string; icon: React.ReactNode;
  prevValues?: { value: string; color: string }[];
}> = ({ label, value, color, icon, prevValues }) => (
  <Card size="small" hoverable
    style={{
      flex: 1, borderRadius: 8, border: `1px solid ${COLORS.borderLight}`,
      transition: 'box-shadow 0.2s, transform 0.15s',
    }}
    styles={{ body: { padding: '16px 12px', textAlign: 'center' as const } }}
  >
    <div style={{ fontSize: 26, marginBottom: 4, lineHeight: 1, color }}>{icon}</div>
    <div style={{ fontSize: 12, color: COLORS.textLight, marginBottom: 4, letterSpacing: 0.3 }}>
      {label}
    </div>
    <div style={{ fontSize: 22, fontWeight: 700, color, lineHeight: 1.2 }}>{value}</div>
    {prevValues && prevValues.length === 2 && (
      <div style={{ fontSize: 11, fontWeight: 600, lineHeight: 1.3, marginTop: 3, opacity: 0.7 }}>
        <span style={{ color: prevValues[0].color }}>{prevValues[0].value}</span>
        <span style={{ color: COLORS.textLight, margin: '0 4px' }}>|</span>
        <span style={{ color: prevValues[1].color }}>{prevValues[1].value}</span>
      </div>
    )}
  </Card>
);

/* ── 区块标题 ── */
const SectionTitle: React.FC<{ title: string; count?: number }> = ({ title, count }) => (
  <div style={{
    fontSize: 14, fontWeight: 700, color: COLORS.textDark, marginBottom: 16, letterSpacing: 0.5,
    display: 'flex', alignItems: 'center', gap: 10,
  }}>
    <span style={{ display: 'inline-block', width: 3, height: 16, borderRadius: 2, background: `linear-gradient(${COLORS.primary}, ${COLORS.purple})` }} />
    {title}
    {count !== undefined && (
      <span style={{ fontSize: 11, fontWeight: 600, color: '#fff', background: COLORS.primary, borderRadius: 10, padding: '0 8px', lineHeight: '18px' }}>
        {count}
      </span>
    )}
  </div>
);

/* ── 框体柱状图（与销售分析风格一致） ── */
const VerticalBars: React.FC<{
  items: { label: string; value: number; color: string; displayValue?: string }[];
  height?: number;
  unit?: string;
  maxSlots?: number;
  groupGaps?: number[];
  gapSize?: number;
  barWidth?: number;
}> = ({ items, height = 120, unit, maxSlots, groupGaps, gapSize = 14, barWidth = 25 }) => {
  const slotCount = maxSlots || items.length;
  const maxVal = items.reduce((m, i) => Math.max(m, i.value), 0);
  const max = maxVal > 0 ? maxVal : 1;
  const ticks = [0, Math.round(max / 2), max].filter((v, i, a) => i === 0 || v !== a[i - 1]);
  const slots = Array.from({ length: slotCount }, (_, i) => items[i] || null);
  return (
    <div style={{ flex: 1 }}>
      <div style={{ display: 'flex', gap: 4 }}>
        <div style={{ width: 28, flexShrink: 0, height, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
          {[...ticks].reverse().map(t => (
            <span key={t} style={{ fontSize: 9, color: '#aaa', textAlign: 'right', lineHeight: 1 }}>{t}{unit}</span>
          ))}
        </div>
        <div style={{ flex: 1, height, position: 'relative', display: 'flex', alignItems: 'flex-end', gap: 2 }}>
          {ticks.map(t => (
            <div key={t} style={{ position: 'absolute', left: 0, right: 0, top: `${(1 - t / max) * 100}%`, borderTop: `1px solid ${COLORS.borderLight}`, pointerEvents: 'none' }} />
          ))}
          {slots.map((item, i) => (
            <div key={i} style={{
              display: 'flex', flexDirection: 'column', alignItems: 'center',
              flex: 1, justifyContent: 'flex-end', alignSelf: 'stretch',
              marginLeft: groupGaps?.includes(i - 1) ? gapSize : 0,
            }}>
              {item && item.color !== 'transparent' ? (
                <>
                  {item.displayValue ? (
                    <div style={{ fontSize: 9, fontWeight: 600, color: item.color, marginBottom: 3, textAlign: 'center', lineHeight: 1.2 }}>
                      {item.displayValue.split('\n').map((line, li) => (
                        <div key={li}>{line}</div>
                      ))}
                    </div>
                  ) : (
                    <span style={{ fontSize: 9, fontWeight: 600, color: item.color, marginBottom: 3, textAlign: 'center', lineHeight: 1.2 }}>{item.value}{unit || ''}</span>
                  )}
                  <div style={{
                    width: barWidth,
                    height: `${Math.max((item.value / max) * 100, 4)}%`, minHeight: 4,
                    border: `3px solid ${item.color}`,
                    background: 'transparent',
                  }} />
                </>
              ) : (
                <div style={{ width: item && item.color === 'transparent' ? 16 : barWidth, height: 0 }} />
              )}
            </div>
          ))}
        </div>
      </div>
      <div style={{ display: 'flex', marginTop: 6, paddingLeft: 32 }}>
        {slots.map((item, i) => (
          <span key={i} style={{
            flex: 1, textAlign: 'center', fontSize: 9, color: COLORS.textSecondary,
            lineHeight: 1.3, opacity: item && item.color !== 'transparent' ? 1 : 0,
            marginLeft: groupGaps?.includes(i - 1) ? gapSize : 0,
          }}>
            {item && item.color !== 'transparent' ? item.label.split('\n').map((l, j) => <span key={j} style={{ display: 'block' }}>{l}</span>) : ''}
          </span>
        ))}
      </div>
    </div>
  );
};

/* ── 饼图（引出线沿圆周分布） ── */
const PieChart: React.FC<{
  items: { label: string; value: number; color: string }[];
  pieSize?: number;
}> = ({ items, pieSize = 130 }) => {
  const total = items.reduce((s, i) => s + i.value, 0);
  if (total === 0) return null;
  const pad = 48;
  const W = pieSize + pad * 2;
  const H = pieSize + pad * 2;
  const cx = W / 2, cy = H / 2, r = pieSize / 2;
  type Slice = { start: number; end: number; label: string; value: number; color: string };
  let cur = 0;
  const slices: Slice[] = items.map(i => {
    const start = (cur / total) * 360;
    cur += i.value;
    return { start, end: (cur / total) * 360, ...i };
  });
  const polar = (angle: number, radius: number) => ({
    x: cx + radius * Math.cos((angle - 90) * Math.PI / 180),
    y: cy + radius * Math.sin((angle - 90) * Math.PI / 180),
  });
  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ display: 'block', overflow: 'visible' }}>
      {slices.map(s => {
        const p1 = polar(s.start, r), p2 = polar(s.end, r);
        const large = s.end - s.start > 180 ? 1 : 0;
        return <path key={s.label} d={`M${cx} ${cy} L${p1.x} ${p1.y} A${r} ${r} 0 ${large} 1 ${p2.x} ${p2.y} Z`} fill={s.color} opacity={0.85} />;
      })}
      <circle cx={cx} cy={cy} r={r * 0.45} fill="#fff" />
      {slices.map(s => {
        const mid = (s.start + s.end) / 2;
        const rad = (mid - 90) * Math.PI / 180;
        const cos = Math.cos(rad), sin = Math.sin(rad);
        const lx = cx + (r + 3) * cos;
        const ly = cy + (r + 3) * sin;
        const tx = cx + (r + 34) * cos;
        const ty = cy + (r + 34) * sin;
        const isRight = cos > 0.3, isLeft = cos < -0.3, isBottom = sin > 0.3;
        const anchor = isRight ? 'start' : isLeft ? 'end' : 'middle';
        const dx = isRight ? 8 : isLeft ? -8 : 0;
        const dy = isBottom ? 18 : -4;
        return (
          <g key={s.label}>
            <line x1={lx} y1={ly} x2={tx} y2={ty} stroke={s.color} strokeWidth={1.5} />
            <circle cx={tx} cy={ty} r={2.5} fill={s.color} />
            <text x={tx + dx} y={ty + dy} textAnchor={anchor} fontSize={11} fill={s.color}>{s.value}</text>
          </g>
        );
      })}
    </svg>
  );
};

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  // message.useMessage();
  const [loading, setLoading] = useState(true);
  const [opportunities, setOpportunities] = useState<SalesOpportunity[]>([]);
  const [approvalRequests, setApprovalRequests] = useState<ApprovalRequest[]>([]);
  const [deliveryProjects, setDeliveryProjects] = useState<DeliveryProject[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [quotationSummaries, setQuotationSummaries] = useState<QuotationSummary[]>([]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    Promise.all([
      opportunityService.list().catch(() => [] as SalesOpportunity[]),
      approvalService.list().catch(() => [] as ApprovalRequest[]),
      deliveryService.list().catch(() => [] as DeliveryProject[]),
      clientService.list().catch(() => [] as Client[]),
      quotationService.list().catch(() => [] as QuotationSummary[]),
    ]).then(([opps, approvals, deliveries, clts, quotes]) => {
      if (!cancelled) {
        setOpportunities(Array.isArray(opps) ? opps : []);
        setApprovalRequests(Array.isArray(approvals) ? approvals : []);
        setDeliveryProjects(Array.isArray(deliveries) ? deliveries.map((p: any) => ({ ...p, nodes: p.nodes || [] })) : []);
        setClients(Array.isArray(clts) ? clts : []);
        setQuotationSummaries(Array.isArray(quotes) ? quotes : []);
        setLoading(false);
      }
    });
    return () => { cancelled = true; };
  }, []);

  const [now] = useState(() => new Date());
const monthlyKpi = useMemo(() => {
    const now = new Date();
    const calcMonth = (offset: number) => {
      const d = new Date(now.getFullYear(), now.getMonth() - offset, 1);
      const mStart = new Date(d.getFullYear(), d.getMonth(), 1);
      const mEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
      const monthOpps = opportunities.filter(o => {
        const created = new Date(o.createdAt);
        const effEnd = (o.status === '过程中' || o.status === '冻结') ? new Date() : new Date(o.updatedAt);
        return created <= mEnd && effEnd >= mStart;
      });
      const monthWins = monthOpps.filter(o => o.status === '赢' && new Date(o.updatedAt) >= mStart && new Date(o.updatedAt) <= mEnd);
      const monthLosses = monthOpps.filter(o => o.status === '输' && new Date(o.updatedAt) >= mStart && new Date(o.updatedAt) <= mEnd);
      const monthNew = opportunities.filter(o => new Date(o.createdAt) >= mStart && new Date(o.createdAt) <= mEnd);
      const activeDel = deliveryProjects.filter(p => p.status !== '已完成');
      const winCnt = monthWins.length, lossCnt = monthLosses.length;
      const total = winCnt + lossCnt;
      return {
        amt: monthOpps.reduce((s, o) => s + o.amount, 0), cnt: monthOpps.length,
        winAmt: monthWins.reduce((s, o) => s + o.amount, 0), winCnt,
        newAmt: monthNew.reduce((s, o) => s + o.amount, 0), newCnt: monthNew.length,
        winRate: total > 0 ? Math.round(winCnt / total * 100) : 0,
        delAmt: activeDel.reduce((s, p) => s + p.contractAmount, 0), delCnt: activeDel.length,
      };
    };
    return [calcMonth(0), calcMonth(1), calcMonth(2)];
  }, [opportunities, deliveryProjects]);

  const recentWins = useMemo(() =>
    opportunities.filter(o => o.status === '赢').sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()).slice(0, 5), [opportunities]);

  const recentLosses = useMemo(() =>
    opportunities.filter(o => o.status === '输').sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()).slice(0, 5), [opportunities]);

  const pendingItems = useMemo(() => approvalRequests.filter(r => r.status === 'pending').slice(0, 5), [approvalRequests]);

  const stageDist = useMemo(() => {
    const stages = ['信息', '线索', '机会', '投标', '议价'];
    const colors = [COLORS.chartGray, COLORS.primary, COLORS.purple, COLORS.warning, COLORS.amber];
    const monthLabels = ['Apr', 'May', 'Jun'];
    const getPipelineStage = (o: typeof opportunities[0], monthEnd: Date) => {
      if (new Date(o.createdAt) > monthEnd) return null;
      if ((o.status === '赢' || o.status === '输') && new Date(o.updatedAt) <= monthEnd) return null;
      return o.stage;
    };
    const result: { label: string; value: number; color: string }[] = [];
    for (const stage of stages) {
      const ci = stages.indexOf(stage);
      for (let mi = 3; mi >= 1; mi--) {
        const d = new Date(now.getFullYear(), now.getMonth() - mi, 1);
        const monthEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
        const count = opportunities.filter(o => getPipelineStage(o, monthEnd) === stage).length;
        result.push({ label: monthLabels[3 - mi], value: count, color: colors[ci] });
      }
    }
    return result;
  }, [opportunities]);

  const getReasonInfo = (reasons: string): { label: string; color: string } => {
    const cat = reasons.split(':')[0];
    const map: Record<string, { label: string; color: string }> = {
      '竞对': { label: '竞对丢单', color: COLORS.danger },
      '取消': { label: '客户取消', color: COLORS.warning },
      '放弃': { label: '我方放弃', color: COLORS.textSecondary },
    };
    return map[cat] || { label: cat, color: COLORS.textSecondary };
  };

  const deliveryStats = useMemo(() => {
    const allNodes = deliveryProjects.flatMap(p => p.nodes || []);
    const getStatusInMonth = (p: typeof deliveryProjects[0], monthEnd: Date): string | null => {
      if (new Date(p.createdAt) > monthEnd) return null;
      if (new Date(p.updatedAt) <= monthEnd) return p.status;
      return '进行中';
    };
    const changedThisMonth = (p: typeof deliveryProjects[0], monthEnd: Date): boolean => {
      const d = new Date(p.updatedAt);
      const monthStart = new Date(monthEnd.getFullYear(), monthEnd.getMonth(), 1);
      return d >= monthStart && d <= monthEnd;
    };
    const monthLabels = ['Apr', 'May', 'Jun'];
    const statusNames = ['已完成', '进行中', '已延期'] as const;
    const statusColors = [COLORS.success, COLORS.primary, COLORS.danger] as const;
    const projectStatus: { label: string; value: number; color: string }[] = [];
    for (let si = 0; si < 3; si++) {
      for (let mi = 3; mi >= 1; mi--) {
        const d = new Date(now.getFullYear(), now.getMonth() - mi, 1);
        const monthEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
        const count = deliveryProjects.filter(p => getStatusInMonth(p, monthEnd) === statusNames[si]).length;
        projectStatus.push({ label: monthLabels[3 - mi], value: count, color: statusColors[si] });
      }
    }
    const getNodeStatusInMonth = (node: typeof allNodes[0], monthEnd: Date): string | null => {
      if (!node || !node.plannedStartDate) return null;
      const start = new Date(node.plannedStartDate);
      if (start > monthEnd) return null;
      if (node.actualDate && new Date(node.actualDate) <= monthEnd) {
        return node.status === 'delayed' ? 'delayed' : 'completed';
      }
      return new Date(node.plannedEndDate) <= monthEnd ? 'delayed' : 'in_progress';
    };
    const nodeStNames = ['completed', 'in_progress', 'delayed', 'pending'] as const;
    const nodeStColors = [COLORS.success, COLORS.primary, COLORS.danger, COLORS.chartGray];
    const nodeStatus: { label: string; value: number; color: string }[] = [];
    for (let si = 0; si < 4; si++) {
      for (let mi = 3; mi >= 1; mi--) {
        const d = new Date(now.getFullYear(), now.getMonth() - mi, 1);
        const monthEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
        const count = allNodes.filter(n => getNodeStatusInMonth(n, monthEnd) === nodeStNames[si]).length;
        nodeStatus.push({ label: monthLabels[3 - mi], value: count, color: nodeStColors[si] });
      }
    }
    const onTimeRate = deliveryProjects.slice(0, 10).map(p => {
      const nodes = p.nodes || [];
      const done = nodes.filter(n => n.status === 'completed' || n.status === 'delayed');
      const delayed = done.filter(n => n.status === 'delayed').length;
      const onTime = done.length - delayed;
      const rate = done.length > 0 ? Math.round((onTime / done.length) * 100) : 0;
      return {
        label: p.clientName.length > 5 ? p.clientName.slice(0, 4) + '…' : p.clientName,
        value: rate,
        color: rate >= 90 ? COLORS.success : rate >= 70 ? COLORS.warning : COLORS.danger,
      };
    });
    // Dashboard 除销售管理外均为未税口径
    const getEstProfit = (p: typeof deliveryProjects[0]) => {
      const q = quotationSummaries.find(q => q.id === p.quotationId);
      const exTax = Math.round(p.contractAmount / 1.13);
      return q ? Math.round(exTax * q.profitRate / 100) : 0;
    };
    const getActProfit = (p: typeof deliveryProjects[0]) => {
      const exTax = Math.round(p.contractAmount / 1.13);
      return p.totalActualCost ? exTax - p.totalActualCost : 0;
    };
    const profitOverview: { label: string; value: number; color: string; displayValue?: string }[] = [];
    for (const prefix of ['概算', '实际'] as const) {
      for (let mi = 3; mi >= 1; mi--) {
        const d = new Date(now.getFullYear(), now.getMonth() - mi, 1);
        const monthEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
        let totalAmt = 0, totalProfit = 0;
        deliveryProjects.forEach(p => {
          const status = getStatusInMonth(p, monthEnd);
          if (prefix === '概算' && status === '进行中') {
            totalProfit += getEstProfit(p);
            totalAmt += p.contractAmount;
          } else if (prefix === '实际' && status === '已完成' && changedThisMonth(p, monthEnd)) {
            totalProfit += getActProfit(p);
            totalAmt += p.contractAmount;
          }
        });
        profitOverview.push({
          label: monthLabels[3 - mi],
          value: Math.round(totalProfit / 1000),
          color: prefix === '概算' ? COLORS.primary : COLORS.success,
          displayValue: totalProfit > 0 ? `${fmtK(totalProfit)}\n（${fmtK(totalAmt)}）` : undefined,
        });
      }
    }
    return { projectStatus, nodeStatus, onTimeRate, profitOverview };
  }, [deliveryProjects, quotationSummaries]);

  const currentFy = useMemo(() => {
    const y = now.getFullYear(), m = now.getMonth();
    const y1 = m >= 6 ? y : y - 1;
    const y2 = m >= 6 ? y + 1 : y;
    return `FY${String(y1 % 100).padStart(2, '0')}${String(y2 % 100).padStart(2, '0')}`;
  }, []);

  const fyTrend = useMemo(() => {
    const fyRange = parseFY(currentFy);
    const fyOpps = opportunities.filter(o => {
      const d = new Date(o.createdAt);
      return d >= fyRange.start && d <= fyRange.end;
    });
    const monthLabels = ['Jul','Aug','Sep','Oct','Nov','Dec','Jan','Feb','Mar','Apr','May','Jun'];
    return Array.from({ length: 12 }, (_, i) => {
      const month = (6 + i) % 12;
      const monthOpps = fyOpps.filter(o => new Date(o.createdAt).getMonth() === month);
      const count = monthOpps.length;
      const amount = monthOpps.reduce((s, o) => s + o.amount, 0);
      return {
        label: monthLabels[i],
        value: count > 0 ? Math.round(amount / 1000) : 0,
        color: COLORS.primary,
        displayValue: count > 0 ? `${fmtK(amount)}\n(${count})` : undefined,
      };
    });
  }, [currentFy, opportunities]);

  const industryDist = useMemo(() => {
    const fyRange = parseFY(currentFy);
    const clientIndustry = new Map(clients.map(c => [c.name, c.industry]));
    const counts: Record<string, number> = {};
    opportunities.forEach(o => {
      const created = new Date(o.createdAt);
      const effectiveEnd = (o.status === '过程中' || o.status === '冻结') ? new Date() : new Date(o.updatedAt);
      if (created <= fyRange.end && effectiveEnd >= fyRange.start) {
        const industry = clientIndustry.get(o.clientName) || '其他';
        counts[industry] = (counts[industry] || 0) + 1;
      }
    });
    const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
    const colors = [COLORS.primary, COLORS.purple, COLORS.warning, COLORS.amber, COLORS.chartGray, COLORS.textSecondary, COLORS.danger];
    return sorted.slice(0, 6).map(([label, value], i) => ({ label, value, color: colors[i] || COLORS.chartGray }));
  }, [currentFy, opportunities, clients]);

  return (
    <div className="dashboard-container">
      {/* ── 标题 ── */}
      <div style={{ fontSize: 20, fontWeight: 700, color: COLORS.textDark, marginBottom: 10, letterSpacing: 0.5 }}>
        仪表盘
      </div>

      {/* ── KPI 卡片行（等宽铺满，与销售分析一致） ── */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 10 }}>
        <KpiCard label="销售机会" value={`${fmtK(monthlyKpi[0].amt)} / ${monthlyKpi[0].cnt}`} color={COLORS.primary} icon="📊"
          prevValues={[
            { value: `${fmtK(monthlyKpi[1].amt)} / ${monthlyKpi[1].cnt}`, color: COLORS.primary },
            { value: `${fmtK(monthlyKpi[2].amt)} / ${monthlyKpi[2].cnt}`, color: COLORS.primary },
          ]} />
        <KpiCard label="本月赢单" value={`${fmtK(monthlyKpi[0].winAmt)} / ${monthlyKpi[0].winCnt}`} color={COLORS.success} icon="🏆"
          prevValues={[
            { value: `${fmtK(monthlyKpi[1].winAmt)} / ${monthlyKpi[1].winCnt}`, color: COLORS.success },
            { value: `${fmtK(monthlyKpi[2].winAmt)} / ${monthlyKpi[2].winCnt}`, color: COLORS.success },
          ]} />
        <KpiCard label="新增机会" value={`${fmtK(monthlyKpi[0].newAmt)} / ${monthlyKpi[0].newCnt}`} color={COLORS.amber} icon="✨"
          prevValues={[
            { value: `${fmtK(monthlyKpi[1].newAmt)} / ${monthlyKpi[1].newCnt}`, color: COLORS.amber },
            { value: `${fmtK(monthlyKpi[2].newAmt)} / ${monthlyKpi[2].newCnt}`, color: COLORS.amber },
          ]} />
        <KpiCard label="赢单率" value={`${monthlyKpi[0].winRate}%`} color={monthlyKpi[0].winRate >= 50 ? COLORS.success : COLORS.warning} icon="🎯"
          prevValues={[
            { value: `${monthlyKpi[1].winRate}%`, color: monthlyKpi[1].winRate >= 50 ? COLORS.success : COLORS.warning },
            { value: `${monthlyKpi[2].winRate}%`, color: monthlyKpi[2].winRate >= 50 ? COLORS.success : COLORS.warning },
          ]} />
        <KpiCard label="交付中" value={`${fmtK(monthlyKpi[0].delAmt)} / ${monthlyKpi[0].delCnt}`} color={COLORS.purple} icon="🚧"
          prevValues={[
            { value: `${fmtK(monthlyKpi[1].delAmt)} / ${monthlyKpi[1].delCnt}`, color: COLORS.purple },
            { value: `${fmtK(monthlyKpi[2].delAmt)} / ${monthlyKpi[2].delCnt}`, color: COLORS.purple },
          ]} />
      </div>

      {/* ── 交付状态 ── */}
      <div style={{ display: 'flex', gap: 20, marginBottom: 10 }}>
        <Card size="small"
          style={{ flex: 1, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '18px 20px' } }}>
          <SectionTitle title="交付状态" />
          <div style={{ display: 'flex', gap: 8, alignItems: 'stretch', minHeight: 150, marginTop: -18 }}>
            <div style={{ flex: 4, display: 'flex', flexDirection: 'column', marginLeft: -20 }}>
              <div style={{ fontSize: 10, color: COLORS.textLight, fontWeight: 500, textAlign: 'right', marginBottom: 2, paddingRight: 2 }}>项目状态</div>
              <VerticalBars items={deliveryStats.projectStatus} height={210} groupGaps={[2, 5]} gapSize={4} />
            </div>
            <div style={{ width: 1, background: COLORS.borderLight, flexShrink: 0 }} />
            <div style={{ flex: 5, display: 'flex', flexDirection: 'column', marginLeft: -10 }}>
              <div style={{ fontSize: 10, color: COLORS.textLight, fontWeight: 500, textAlign: 'right', marginBottom: 2, paddingRight: 2 }}>节点执行</div>
              <VerticalBars items={deliveryStats.nodeStatus} height={210} groupGaps={[2, 5, 8]} gapSize={5} />
            </div>
            <div style={{ width: 1, background: COLORS.borderLight, flexShrink: 0 }} />
            <div style={{ flex: 6, display: 'flex', flexDirection: 'column' }}>
              <div style={{ fontSize: 10, color: COLORS.textLight, fontWeight: 500, textAlign: 'right', marginBottom: 2, paddingRight: 2 }}>节点准时率</div>
              <VerticalBars items={deliveryStats.onTimeRate} height={210} unit="%" maxSlots={18} />
            </div>
            <div style={{ width: 1, background: COLORS.borderLight, flexShrink: 0 }} />
            <div style={{ flex: 4, display: 'flex', flexDirection: 'column' }}>
              <div style={{ fontSize: 10, color: COLORS.textLight, fontWeight: 500, textAlign: 'right', marginBottom: 2, paddingRight: 2 }}>利润概览</div>
              <VerticalBars items={deliveryStats.profitOverview} height={210} unit="K" />
            </div>
          </div>
        </Card>
      </div>

      {/* ── 底栏：管道节点 | 行业分布 | 机会趋势 ── */}
      <div style={{ display: 'flex', gap: 20, flexWrap: 'wrap' }}>
        <Card size="small"
          style={{ flex: '1 1 220px', minWidth: 190, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '16px 18px' } }}>
          <SectionTitle title="管道节点" />
          {stageDist.every(s => s.value === 0) ? (
            <div style={{ padding: 24, textAlign: 'center', color: COLORS.textLight, fontSize: 13 }}>暂无活跃管道</div>
          ) : (
            <div style={{ marginTop: 50, marginLeft: -20 }}>
              <VerticalBars items={stageDist} height={250} groupGaps={[2, 5, 8, 11]} />
            </div>
          )}
        </Card>

        <Card size="small"
          style={{ flex: '1 1 283px', minWidth: 233, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '16px 18px' } }}>
          <SectionTitle title="行业分布" count={industryDist.reduce((s, i) => s + i.value, 0)} />
          {industryDist.length === 0 ? (
            <div style={{ padding: 24, textAlign: 'center', color: COLORS.textLight, fontSize: 13 }}>暂无数据</div>
          ) : (
            <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginTop: -20 }}>
              <div style={{ flex: 1, display: 'flex', justifyContent: 'center', overflow: 'visible' }}>
                <PieChart items={industryDist} pieSize={240} />
              </div>
              <div style={{ flexShrink: 0, display: 'flex', flexDirection: 'column', gap: 6 }}>
                {industryDist.map(i => (
                  <div key={i.label} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <span style={{ width: 8, height: 8, borderRadius: '50%', background: i.color, flexShrink: 0 }} />
                    <span style={{ fontSize: 11, color: COLORS.textSecondary, whiteSpace: 'nowrap' }}>{i.label}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </Card>

        <Card size="small"
          style={{ flex: '1 1 397px', minWidth: 337, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '16px 18px' } }}>
          <SectionTitle title="机会趋势" count={fyTrend.reduce((s, m) => s + m.value, 0)} />
          {fyTrend.every(m => m.value === 0) ? (
            <div style={{ padding: 24, textAlign: 'center', color: COLORS.textLight, fontSize: 13 }}>当前财年暂无新增</div>
          ) : (
            <div style={{ marginTop: 50 }}>
              <VerticalBars items={fyTrend} height={250} unit="K" />
            </div>
          )}
        </Card>
      </div>

      {/* ── 动态：近期赢单 | 待审批项 | 近期输单 ── */}
      <div style={{ display: 'flex', gap: 20, marginTop: 10, flexWrap: 'wrap' }}>
        <Card size="small"
          style={{ flex: '1 1 380px', minWidth: 300, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '4px 16px' } }}>
          <SectionTitle title="近期赢单" count={recentWins.length} />
          {recentWins.length === 0 ? (
            <div style={{ padding: 24, textAlign: 'center', color: COLORS.textLight, fontSize: 13 }}>暂无赢单记录</div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {recentWins.map(o => (
                <div key={o.id} onClick={() => navigate('/opportunities')}
                  style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', padding: '4px 8px', borderRadius: 6, transition: 'background 0.12s' }}
                  onMouseEnter={e => e.currentTarget.style.background = COLORS.bgSelected}
                  onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                  <span style={{ fontSize: 18, lineHeight: 1, color: COLORS.success }}><TrophyOutlined /></span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: COLORS.textDark, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{o.clientName}</div>
                    <div style={{ fontSize: 11, color: COLORS.textLight, display: 'flex', gap: 10, marginTop: 1 }}>
                      <span>{o.salesman}</span>
                      <span>{o.updatedAt}</span>
                    </div>
                  </div>
                  <span style={{ fontSize: 14, fontWeight: 700, color: COLORS.success, whiteSpace: 'nowrap' }}>¥{fmtK(o.amount)}</span>
                  <RightOutlined style={{ color: COLORS.textLight, fontSize: 12 }} />
                </div>
              ))}
            </div>
          )}
        </Card>

        <Card size="small"
          style={{ flex: '1 1 380px', minWidth: 300, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '4px 16px' } }}>
          <SectionTitle title="待审批项" count={pendingItems.length} />
          {pendingItems.length === 0 ? (
            <div style={{ padding: 24, textAlign: 'center', color: COLORS.textLight, fontSize: 13 }}>暂无待审批项</div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {pendingItems.map(r => (
                <div key={r.id} onClick={() => navigate('/approval')}
                  style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', padding: '4px 8px', borderRadius: 6, transition: 'background 0.12s' }}
                  onMouseEnter={e => e.currentTarget.style.background = COLORS.bgSelected}
                  onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                  <span style={{ fontSize: 18, lineHeight: 1, color: COLORS.warning }}><ClockCircleOutlined /></span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: COLORS.textDark, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.clientName}</div>
                    <div style={{ fontSize: 11, color: COLORS.textLight, display: 'flex', gap: 10, marginTop: 1 }}>
                      <span>{r.submitter}</span>
                      <span>{r.submitTime}</span>
                      <span style={{ color: COLORS.textSecondary }}>¥{fmtK(r.amount)}</span>
                    </div>
                  </div>
                  <Tag color={r.approvalType === 'quotation' ? COLORS.primary : r.approvalType === 'plan' ? COLORS.warning : COLORS.success}
                    style={{ margin: 0, fontSize: 11, fontWeight: 600, border: 'none', borderRadius: 4, padding: '1px 8px' }}>
                    {{ quotation: '报价', plan: '计划', cost: '成本' }[r.approvalType]}
                  </Tag>
                  <RightOutlined style={{ color: COLORS.textLight, fontSize: 12 }} />
                </div>
              ))}
            </div>
          )}
        </Card>

        <Card size="small"
          style={{ flex: '1 1 380px', minWidth: 300, borderRadius: 8, border: `1px solid ${COLORS.borderLight}` }}
          styles={{ body: { padding: '4px 16px' } }}>
          <SectionTitle title="近期输单" count={recentLosses.length} />
          {recentLosses.length === 0 ? (
            <div style={{ padding: 24, textAlign: 'center', color: COLORS.textLight, fontSize: 13 }}>暂无输单记录</div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {recentLosses.map(o => {
                const reason = getReasonInfo(o.reasons || '');
                return (
                  <div key={o.id} onClick={() => navigate('/opportunities')}
                    style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', padding: '4px 8px', borderRadius: 6, transition: 'background 0.12s' }}
                    onMouseEnter={e => e.currentTarget.style.background = COLORS.bgSelected}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                    <span style={{ fontSize: 14 }}>❌</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, fontWeight: 600, color: COLORS.textDark, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{o.clientName}</div>
                      <div style={{ fontSize: 11, color: COLORS.textLight, display: 'flex', gap: 10, marginTop: 1 }}>
                        <span>{o.salesman}</span>
                        <span>{o.updatedAt}</span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
                      <span style={{ fontSize: 14, fontWeight: 700, color: COLORS.textSecondary, whiteSpace: 'nowrap' }}>¥{fmtK(o.amount)}</span>
                      <Tag color={reason.color}
                        style={{ margin: 0, fontSize: 11, fontWeight: 600, border: 'none', borderRadius: 4, padding: '1px 8px' }}>
                        {reason.label}
                      </Tag>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Card } from 'antd';
import { deliveryService } from '../services/deliveryService';
import type { DeliveryProject } from '../types';
import { COLORS } from '../styles/colors';
import { NODE_DISPLAY_NAMES } from '../utils/constants';
import { computeDeliveryEstGP3 } from '../utils/calculations';
import { parseFY, FYSelector } from '../utils/fiscalYear';
import { fmtK, loadQuotationGroups, preloadQuotationGroupsBatch } from '../utils/analysisShared';
import { VerticalBarChart, ProfitChart, ProjectGantt, BubbleChart } from '../components/charts/DeliveryCharts';
import type { ProfitItem, BubbleDataItem } from '../components/charts/DeliveryCharts';

/* ============================================================
   财年工具
   ============================================================ */
/** 将名称截取前5个字符，再拆为两行显示 */
function splitLabel(name: string): string {
  const s = name.length > 5 ? name.slice(0, 5) : name;
  if (s.length <= 2) return s;
  const mid = Math.ceil(s.length / 2);
  return s.slice(0, mid) + '\n' + s.slice(mid);
}

/* ============================================================
   子组件 — 概览卡片
   ============================================================ */
interface KpiCard {
  label: string; value: string; color: string; icon: string;
  subValue?: string;
  prevValues?: { value: string; color: string }[];
}
const OverviewCards: React.FC<{ items: KpiCard[] }> = ({ items }) => (
  <div style={{ display: 'flex', gap: 16, marginBottom: 24 }}>
    {items.map(item => (
      <Card key={item.label} size="small"
        style={{
          flex: 1, borderRadius: 8, border: `1px solid ${COLORS.borderLight}`,
          transition: 'box-shadow 0.2s, transform 0.15s',
        }}
        styles={{ body: { padding: '16px 12px', textAlign: 'center' as const } }}
        hoverable
      >
        <div style={{ fontSize: 20, marginBottom: 2 }}>{item.icon}</div>
        <div style={{ fontSize: 12, color: COLORS.textLight, marginBottom: 4, letterSpacing: 0.3 }}>
          {item.label}
        </div>
        <div style={{ fontSize: 26, fontWeight: 700, color: item.color, lineHeight: 1.2 }}>
          {item.value}
        </div>
        {item.subValue && (
          <div style={{ fontSize: 13, fontWeight: 600, color: item.color, marginTop: 2 }}>
            {item.subValue}
          </div>
        )}
        {item.prevValues && item.prevValues.length === 2 && (
          <div style={{ fontSize: 11, fontWeight: 600, lineHeight: 1.3, marginTop: 3, opacity: 0.7 }}>
            <span style={{ color: item.prevValues[0].color }}>{item.prevValues[0].value}</span>
            <span style={{ color: COLORS.textLight, margin: '0 4px' }}>|</span>
            <span style={{ color: item.prevValues[1].color }}>{item.prevValues[1].value}</span>
          </div>
        )}
      </Card>
    ))}
  </div>
);


/* ============================================================
   主组件
   ============================================================ */
const DeliveryAnalysis: React.FC = () => {
  const defaultFy = `FY${String(new Date().getFullYear() % 100).padStart(2,'0')}${String((new Date().getFullYear() + 1) % 100).padStart(2,'0')}`;
const [fySelect, setFySelect] = useState(defaultFy);
  const [deliveryProjects, setDeliveryProjects] = useState<DeliveryProject[]>([]);
  const [dpLoading, setDpLoading] = useState(true);

  useEffect(() => {
    setDpLoading(true);
    deliveryService.list()
      .then((data: any[]) => setDeliveryProjects((data || []).map((p: any) => ({ ...p, nodes: p.nodes || [] }))))
      .catch(() => setDeliveryProjects([]))
      .finally(() => setDpLoading(false));
  }, []);

  // 交货项目加载完成后，预加载报价数据到缓存
  useEffect(() => {
    const ids = deliveryProjects.filter(p => p.quotationId).map(p => p.quotationId);
    if (ids.length > 0) preloadQuotationGroupsBatch(ids);
  }, [deliveryProjects]);

  // ── 共享工具函数 ──
  /** 计算某项目的最大延期天数 */
  const calcMaxDelay = (p: DeliveryProject, now: Date) => {
    let maxDelay = 0;
    for (const n of p.nodes) {
      if (n.status === 'completed') continue;
      const plannedEnd = new Date(n.plannedEndDate);
      const days = Math.round((now.getTime() - plannedEnd.getTime()) / (1000 * 60 * 60 * 24));
      if (days > maxDelay) maxDelay = days;
    }
    return maxDelay;
  };
  /** 判断项目节点15是否已完成且在财年范围内 */
  const isNode15CompletedInFy = (p: DeliveryProject, fyRange: ReturnType<typeof parseFY>) => {
    const n15 = p.nodes.find(n => n.nodeNo === 15);
    if (!n15 || n15.status !== 'completed') return false;
    const d = new Date(n15.actualDate || p.updatedAt);
    return d >= fyRange.start && d <= fyRange.end;
  };

  // ── 缓存财年范围 ──
  const fyRange = useMemo(() => parseFY(fySelect), [fySelect]);

  // ── 财年过滤（活跃期交集：与销售分析一致的逻辑）──
  const fyFiltered = useMemo(() => {
    return deliveryProjects.filter(p => {
      const created = new Date(p.createdAt);
      const effectiveEnd = (p.status === '进行中' || p.status === '已延期')
        ? new Date()
        : new Date(p.updatedAt);
      return created <= fyRange.end && effectiveEnd >= fyRange.start;
    });
  }, [deliveryProjects, fyRange]);

  // ── 各项目延期天数 ──
  const projectDelayDays = useMemo(() => {
    const now = new Date();
    return fyFiltered.map(p => {
      const maxDelay = calcMaxDelay(p, now);
      return {
        name: splitLabel(p.clientName),
        value: maxDelay,
        color: maxDelay > 0 ? COLORS.danger : COLORS.success,
      };
    });
  }, [fyFiltered]);

  // ── 节点卡脖子分析（瓶颈识别）──
  const nodeBottleneck = useMemo(() => {
    const now = new Date();
    const delayed = new Array(15).fill(0);
    const reached = new Array(15).fill(0);
    const delayedProjects: string[][] = Array.from({ length: 15 }, () => []);

    for (const p of fyFiltered) {
      if (p.status !== '进行中' && p.status !== '已延期' && p.status !== '已完成') continue;
      const shortName = p.clientName.length > 4 ? p.clientName.slice(0, 4) : p.clientName;
      for (const n of p.nodes) {
        // 该项目是否已到达此节点（计划截止日已过，或节点已启动/完成）
        if (n.status === 'pending' && new Date(n.plannedEndDate) > now) continue;
        reached[n.nodeNo - 1]++;

        // 在该节点是否延期
        let isDelayed = n.status === 'delayed';
        if (!isDelayed && n.status !== 'completed') {
          const plannedEnd = new Date(n.plannedEndDate);
          if (plannedEnd < now) isDelayed = true;
        }
        if (isDelayed) { delayed[n.nodeNo - 1]++; delayedProjects[n.nodeNo - 1].push(shortName); }
      }
    }
    return NODE_DISPLAY_NAMES.map((name, i) => ({
      name, value: delayed[i],
      subValue: delayed[i] > 0 ? reached[i] : undefined,
      tooltip: delayed[i] > 0 && delayedProjects[i].length > 0
        ? `${name}：${delayed[i]}/${reached[i]} 个项目\n${[...new Set(delayedProjects[i])].join('、')}`
        : undefined,
      color: delayed[i] > 0 ? (delayed[i] >= 2 ? COLORS.danger : COLORS.warning) : '#ccc',
    }));
  }, [fyFiltered]);

  // ── 利润分析数据（仅已完成项目总结的项目，按GP3偏差排序）──
  const profitChartData = useMemo(() => {
    const completed = fyFiltered.filter(p => isNode15CompletedInFy(p, fyRange));
    const itemData = completed.map(p => {
      const { groups, version } = loadQuotationGroups(p.quotationId);
      const { exTax, grandEstimated, estGP3 } = computeDeliveryEstGP3(p.contractAmount, groups, version);
      const actProfit = p.totalActualCost != null ? (exTax - p.totalActualCost) : undefined;
      const actGP3 = actProfit != null && exTax > 0 ? actProfit / exTax : undefined;
      return { exTax, estGP3, actGP3, actProfit, deviation: actGP3 != null ? actGP3 - estGP3 : 0, name: splitLabel(p.clientName), estProfit: exTax - grandEstimated };
    });
    const items: ProfitItem[] = itemData.map(d => ({ name: d.name, estProfit: d.estProfit, estGP3: d.estGP3, actProfit: d.actProfit, actGP3: d.actGP3, deviation: d.deviation }))
      .sort((a, b) => Math.abs(b.deviation) - Math.abs(a.deviation));
    const totalAmt = itemData.reduce((s, d) => s + d.exTax, 0);
    const avgEstGP3 = totalAmt > 0 ? itemData.reduce((s, d) => s + d.exTax * d.estGP3, 0) / totalAmt : 0;
    const actItems = itemData.filter(d => d.actGP3 != null);
    const avgActGP3 = actItems.length > 0 ? actItems.reduce((s, d) => s + d.exTax * d.actGP3!, 0) / actItems.reduce((s, d) => s + d.exTax, 0) : 0;
    return { items, avgEstGP3, avgActGP3 };
  }, [fyFiltered, fyRange]);

  // ── 健康 KPI 卡片 ──
  const overviewItems = useMemo((): KpiCard[] => {
    const now = new Date();
    let totalDelayDays = 0, delayProjectCount = 0;
    let onTimeCompleted = 0, totalCompleted = 0;
    let costDevNumerator = 0, costDevDenominator = 0;

    const totalCount = fyFiltered.length;
    const activeCount = fyFiltered.filter(p => p.nodes.find(n => n.nodeNo === 15)?.status !== 'completed').length;
    const delayedCount = fyFiltered.filter(p => p.status === '已延期').length;
    const completedCount = fyFiltered.filter(p => isNode15CompletedInFy(p, fyRange)).length;
    let totalAmt = 0, activeAmt = 0, completedAmt = 0, delayedAmt = 0;
    for (const p of fyFiltered) {
      const exTax = Math.round(p.contractAmount / (1 + 0.13));
      totalAmt += exTax;
      const n15Done = p.nodes.find(n => n.nodeNo === 15)?.status === 'completed';
      if (!n15Done) activeAmt += exTax;
      if (p.status === '已延期') delayedAmt += exTax;
      if (isNode15CompletedInFy(p, fyRange)) completedAmt += exTax;
      // 加权延期天数：各项目最大延期天数的平均
      const maxDelay = calcMaxDelay(p, now);
      if (maxDelay > 0) { totalDelayDays += maxDelay; delayProjectCount++; }

      // 节点按时完成率
      for (const n of p.nodes) {
        if (n.status === 'completed' || n.status === 'delayed') {
          totalCompleted++;
          if (n.actualDate && new Date(n.actualDate) <= new Date(n.plannedEndDate)) onTimeCompleted++;
        }
      }

      // 成本偏差率
      if (p.costStatus === 'approved' && p.totalActualCost != null) {
        const { groups, version } = loadQuotationGroups(p.quotationId);
        const { totalEstimated } = computeDeliveryEstGP3(p.contractAmount, groups, version);
        costDevNumerator += (p.totalActualCost - totalEstimated);
        costDevDenominator += totalEstimated;
      }
    }

    const avgDelay = delayProjectCount > 0 ? Math.round(totalDelayDays / delayProjectCount) : 0;
    const onTimeRate = totalCompleted > 0 ? Math.round(onTimeCompleted / totalCompleted * 100) : 100;
    const costDevRate = costDevDenominator > 0 ? (costDevNumerator / costDevDenominator * 100) : 0;

    return [
      { label: '项目总数', value: fmtK(totalAmt) + ' / ' + totalCount, color: COLORS.primary, icon: '📊' },
      { label: '进行中项目', value: fmtK(activeAmt) + ' / ' + activeCount, color: COLORS.primary, icon: '🚧' },
      { label: '已完成项目', value: fmtK(completedAmt) + ' / ' + completedCount, color: COLORS.success, icon: '✅' },
      { label: '延期项目', value: fmtK(delayedAmt) + ' / ' + delayedCount, color: delayedCount > 0 ? COLORS.danger : COLORS.success, icon: '🚨' },
      { label: '加权延期天数', value: `${avgDelay}天`, color: avgDelay > 0 ? COLORS.danger : COLORS.success, icon: '📅' },
      { label: '节点按时率', value: `${onTimeRate}%`, color: onTimeRate >= 80 ? COLORS.success : onTimeRate >= 50 ? COLORS.warning : COLORS.danger, icon: '🎯' },
      { label: '成本偏差率', value: costDevDenominator > 0 ? `${costDevRate > 0 ? '+' : ''}${costDevRate.toFixed(1)}%` : '—', color: costDevRate <= 0 ? COLORS.success : COLORS.danger, icon: '💰' },
    ];
  }, [fyFiltered, fyRange]);

  // ── 按月交付 KPI（最近3个完整月） ──
  const monthlyDelKpi = useMemo(() => {
    const now = new Date();
    const calcMonth = (offset: number) => {
      const d = new Date(now.getFullYear(), now.getMonth() - offset, 1);
      const mEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
      const mp = deliveryProjects.filter(p => new Date(p.createdAt) <= mEnd);
      let tAmt = 0, aAmt = 0, cAmt = 0, dAmt = 0, tDelay = 0, dCnt = 0, onT = 0, tN = 0;
      let active = 0, completed = 0, delayed = 0;
      for (const p of mp) {
        const ex = Math.round(p.contractAmount / 1.13);
        tAmt += ex;
        const n15 = p.nodes.find(n => n.nodeNo === 15);
        const n15done = n15?.status === 'completed' && !!n15.actualDate && new Date(n15.actualDate) <= mEnd;
        if (n15done) { completed++; cAmt += ex; } else { active++; aAmt += ex; }
        if (p.status === '已延期') { delayed++; dAmt += ex; }
        const md = calcMaxDelay(p, mEnd);
        if (md > 0) { tDelay += md; dCnt++; }
        for (const n of p.nodes) {
          if (n.status === 'completed' || n.status === 'delayed') { tN++; if (n.actualDate && new Date(n.actualDate) <= new Date(n.plannedEndDate)) onT++; }
        }
      }
      return { total: mp.length, tAmt, active, aAmt, completed, cAmt, delayed, dAmt, avgDelay: dCnt > 0 ? Math.round(tDelay / dCnt) : 0, onTimeRate: tN > 0 ? Math.round(onT / tN * 100) : 100 };
    };
    return [calcMonth(1), calcMonth(2), calcMonth(3)];
  }, [deliveryProjects]);

  // ── 甘特图数据（12个月时间线，仅显示在时间范围内的节点）──
  const ganttData = useMemo(() => {
    const now = new Date();
    const tlStart = new Date(now.getFullYear(), now.getMonth() - 5, 1);
    const tlEnd = new Date(now.getFullYear(), now.getMonth() + 6, 0);
    const DAY_MS = 1000 * 60 * 60 * 24;
    const totalDays = Math.round((tlEnd.getTime() - tlStart.getTime()) / DAY_MS);
    const months = Array.from({ length: 12 }, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth() - 5 + i, 1);
      return d.toLocaleString('en', { month: 'short' });
    });
    const todayPos = Math.round((now.getTime() - tlStart.getTime()) / DAY_MS);
    const currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const projectRows = fyFiltered.filter(p => {
      const n15 = p.nodes.find(n => n.nodeNo === 15);
      if (n15 && n15.status === 'completed') {
        const doneDate = n15.actualDate ? new Date(n15.actualDate) : new Date(p.updatedAt);
        return doneDate >= currentMonthStart;
      }
      return true;
    }).map(p => {
      const slots = p.nodes.map(n => {
        const startH = n.history.find(h => h.field === 'status' && h.newValue === 'in_progress');
        let start: Date, end: Date;
        if (n.status === 'completed') {
          start = startH ? new Date(startH.changedAt) : new Date(n.plannedStartDate);
          end = n.actualDate ? new Date(n.actualDate) : new Date(n.plannedEndDate);
        } else if (n.status === 'in_progress') {
          start = new Date(n.plannedStartDate);
          end = now;
        } else {
          start = new Date(n.plannedStartDate);
          end = new Date(n.plannedEndDate);
        }
        // 初始计划时间：从 history 中找最早的 plannedDate 变更前的值
        const planChanges = n.history.filter(h => h.field === 'plannedDate')
          .sort((a, b) => new Date(a.changedAt).getTime() - new Date(b.changedAt).getTime());
        const initStart = planChanges.length > 0
          ? new Date(planChanges[0].oldValue)
          : new Date(n.plannedStartDate);
        const initEnd = planChanges.length > 0
          ? new Date(planChanges[planChanges.length - 1].oldValue)
          : new Date(n.plannedEndDate);
        return { nodeNo: n.nodeNo, startDate: start, endDate: end, status: n.status,
          name: n.name, plannedStartDate: new Date(n.plannedStartDate),
          plannedEndDate: new Date(n.plannedEndDate), actualDate: n.actualDate ? new Date(n.actualDate) : undefined,
          initStartDate: initStart, initEndDate: initEnd };
      });
      return { name: p.clientName, slots };
    });
    return { tlStart, totalDays, months, todayPos, projectRows, DAY_MS };
  }, [fyFiltered]);

  // ── 所有 fyFiltered 项目的生命周期（用于甘特图负载压力线）──
  const projectLifecycles = useMemo(() => {
    const now = new Date();
    return fyFiltered.map(p => {
      const node1 = p.nodes.find(n => n.nodeNo === 1);
      if (!node1) return null;
      // null items filtered below
      const node15 = p.nodes.find(n => n.nodeNo === 15);
      const start = new Date(node1.plannedStartDate);
      // 已完成项目用实际完成日，未完成项目取 updatedAt / 末节点计划完成日 / now 三者最晚
      const end = node15?.actualDate
        ? new Date(node15.actualDate)
        : new Date(Math.max(
            new Date(p.updatedAt).getTime(),
            new Date(p.nodes[p.nodes.length - 1].plannedEndDate).getTime(),
            now.getTime()
          ));
      const { groups, version } = loadQuotationGroups(p.quotationId);
      const { exTax } = computeDeliveryEstGP3(p.contractAmount, groups, version);
      return { id: p.id, start, end, exTax };
    }).filter(Boolean) as { id: string; start: Date; end: Date; exTax: number }[];
  }, [fyFiltered]);

  // ── 气泡图数据（仅含当前财年内完成节点15的项目）──
  // 产能压力：按实际时间窗口计算并行项目的时间加权贡献
  // 公式：加权金额 × (1 + k × max(0, 加权个数 - 1))，k=0.2，显示值/10000
  const bubbleData = useMemo(() => {
    const now = new Date();
    const k = 0.2;

    // 当前财年内完成(节点15)的项目
    const completed = fyFiltered.filter(p => isNode15CompletedInFy(p, fyRange));

    // 构建所有 fyFiltered 项目的实际生命周期（回顾性分析用实际完成时间）
    const lifecycles = new Map<string, { start: Date; end: Date; exTax: number }>();
    for (const p of fyFiltered) {
      const node1 = p.nodes.find(n => n.nodeNo === 1);
      if (!node1) continue;
      const node15 = p.nodes.find(n => n.nodeNo === 15);
      // 实际开始 = 节点1计划开始（无实际开始日期字段时的最佳近似）
      const start = new Date(node1.plannedStartDate);
      // 实际结束 = 节点15实际完成（如有），否则使用最近更新时间或现在
      const end = node15?.actualDate
        ? new Date(node15.actualDate)
        : new Date(p.updatedAt);
      const { groups, version } = loadQuotationGroups(p.quotationId);
      const { exTax } = computeDeliveryEstGP3(p.contractAmount, groups, version);
      lifecycles.set(p.id, { start, end, exTax });
    }

    return completed.filter(p => {const n1 = p.nodes.find(n => n.nodeNo === 1); return n1 != null;}).map(p => {
      const lc = lifecycles.get(p.id); if (!lc) return null;
      // null items filtered below
      const projDuration = lc.end.getTime() - lc.start.getTime();

      const maxDelay = calcMaxDelay(p, now);
      const { groups, version } = loadQuotationGroups(p.quotationId);
      const { exTax, totalEstimated } = computeDeliveryEstGP3(p.contractAmount, groups, version);
      const costDev = p.totalActualCost != null && totalEstimated > 0
        ? (p.totalActualCost - totalEstimated) / totalEstimated * 100 : 0;

      // 时间加权并行计算
      let weightedAmount = 0;
      let weightedCount = 0;

      for (const [otherId, otherLc] of lifecycles) {
        if (otherId === p.id) continue;

        const overlapStart = Math.max(lc.start.getTime(), otherLc.start.getTime());
        const overlapEnd = Math.min(lc.end.getTime(), otherLc.end.getTime());
        const overlapDuration = Math.max(0, overlapEnd - overlapStart);

        if (overlapDuration <= 0) continue;

        const overlapFrac = overlapDuration / projDuration;
        weightedAmount += otherLc.exTax * overlapFrac;
        weightedCount += overlapFrac;
      }

      const capacityRaw = weightedAmount * (1 + k * Math.max(0, weightedCount - 1));

      return {
        name: p.clientName,
        contractAmount: exTax,
        delayDays: maxDelay,
        costDeviation: costDev,
        status: p.status,
        capacityPressure: capacityRaw / 10000,
      };
    }).filter(Boolean) as BubbleDataItem[];
  }, [fyFiltered, fyRange]);

  // ── 渲染 ──
  // 左列每张卡片高度 = 边框2 + padding-top30 + SVG225 = 257px，间隔16px
  const CARD_BORDER = 2, CARD_PAD_TOP = 30, SVG_H = 225, GAP = 16;
  const CARD_TOTAL = CARD_BORDER + CARD_PAD_TOP + SVG_H; // 257
  const LEFT_COL_H = CARD_TOTAL * 3 + GAP * 2; // 803
  // 气泡图卡片
  const BUBBLE_PAD_TOP = 37; // 原22 + 15
  const BUBBLE_PAD_BOTTOM = 25; // 原10 + 15
  const BUBBLE_SVG_H = LEFT_COL_H - 2 - BUBBLE_PAD_TOP - BUBBLE_PAD_BOTTOM; // 739
  // 画布高度 = 左列总高 − 原始border(2) − 原始padding-bottom(10) − 原始padding-top(22) = 769
  // 再 − 原缩减30px + 标签下移合计25px = 764
  const BUBBLE_ORIG_PAD_TOP = 22, BUBBLE_ORIG_PAD_BOT = 10;
  const BUBBLE_CANVAS_SHRINK = 30; // 原高度缩减
  const BUBBLE_LABEL_OFFSET = 15 + 10; // "延期天数"标签两次下移
  const BUBBLE_CANVAS_H = LEFT_COL_H - 2 - BUBBLE_ORIG_PAD_BOT - BUBBLE_ORIG_PAD_TOP - BUBBLE_CANVAS_SHRINK + BUBBLE_LABEL_OFFSET; // 764
  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <span style={{ fontSize: 17, fontWeight: 700, color: COLORS.textDark }}>交付分析</span>
        <FYSelector value={fySelect} onChange={setFySelect} />
      </div>


      <OverviewCards items={overviewItems.map((item, i) => {
            const mk = monthlyDelKpi;
            const v1 = [`${fmtK(mk[1].tAmt)} / ${mk[1].total}`, `${fmtK(mk[1].aAmt)} / ${mk[1].active}`, `${fmtK(mk[1].cAmt)} / ${mk[1].completed}`, `${fmtK(mk[1].dAmt)} / ${mk[1].delayed}`, `${mk[1].avgDelay}天`, `${mk[1].onTimeRate}%`, ''];
            const v2 = [`${fmtK(mk[2].tAmt)} / ${mk[2].total}`, `${fmtK(mk[2].aAmt)} / ${mk[2].active}`, `${fmtK(mk[2].cAmt)} / ${mk[2].completed}`, `${fmtK(mk[2].dAmt)} / ${mk[2].delayed}`, `${mk[2].avgDelay}天`, `${mk[2].onTimeRate}%`, ''];
            return { ...item, prevValues: [{ value: v1[i] || '', color: item.color }, { value: v2[i] || '', color: item.color }] };
          })} />

          <div style={{ display: 'flex', gap: 16, marginTop: 16, alignItems: 'stretch' }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, flex: '0 0 calc(3 / 7 * (100% - 96px) + 32px)' }}>
              <ProfitChart data={profitChartData.items}
                avgEstGP3={profitChartData.avgEstGP3}
                avgActGP3={profitChartData.avgActGP3}
                height={225} chartWidth={702} contentOffset={30} />
              <VerticalBarChart title="延期天数" data={projectDelayDays}
                format="num" height={225} topN={15} barWidthRatio={0.75}
                maxBarWidth={40} chartWidth={702} contentOffset={30} hideAvgLine padTop={27} padBottom={33} barLabelGap={10} />
              <VerticalBarChart title="节点分析" data={nodeBottleneck}
                format="num" height={225} topN={15} barWidthRatio={0.75}
                maxBarWidth={40} chartWidth={702} contentOffset={30} hideAvgLine padTop={27} padBottom={33} disableSort />
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16, flex: 1, minWidth: 0 }}>
              <BubbleChart data={bubbleData} height={BUBBLE_SVG_H} canvasHeight={BUBBLE_CANVAS_H} bodyPadTop={BUBBLE_PAD_TOP} bodyPadBottom={BUBBLE_PAD_BOTTOM} />
            </div>
          </div>

          {/* Row 4: 项目节点甘特图 */}
          <div style={{ minHeight: 750, marginTop: 26 }}>
            <ProjectGantt data={ganttData.projectRows}
              tlStart={ganttData.tlStart} totalDays={ganttData.totalDays}
              months={ganttData.months} todayPos={ganttData.todayPos}
              lifecycles={projectLifecycles}
              height={750} />
          </div>
      </div>
      );
};

export default DeliveryAnalysis;

