        fi({ itemNo: 2, itemType: 'COMPONENT', code: 'SV-WSRENT-000000-V1.0', description: '场地租赁', qtyTotal: 1, unit: '项', sourcingType: 'SELF_MANUFACTURED', unitCost: 0, designHours: 0, assemblyHours: 0, marginRate: 0.1, hasWarranty: false }),
      ]},
