source:
import React, { useState, useMemo, useCallback, useEffect } from 'react';

import { useNavigate } from 'react-router-dom';

import { Button, Table, Tag, Input, Select, Modal, message, Dropdown, Tooltip } from 'antd';

import { PlusOutlined, EditOutlined, FileAddOutlined, CheckCircleOutlined, CloseCircleOutlined, PauseCircleOutlined, PlayCircleOutlined, CheckOutlined, CloseOutlined, StopOutlined } from '@ant-design/icons';


import BlueTableModal from '../components/BlueTableModal';
import type { SalesOpportunity, DeliveryNode, BlueTable } from '../types';
import { REASON_TAXONOMY, formatReasons } from '../reasonTaxonomy';
import { parseFY, FYSelector } from '../utils/fiscalYear';

import { COLORS } from '../styles/colors';
import { opportunityService } from '../services/opportunityService';
import { quotationService } from '../services/quotationService';
import { projectService } from '../services/projectService';
import { deliveryService } from '../services/deliveryService';
import { approvalService } from '../services/approvalService';
import { clientService } from '../services/clientService';
import { calcBlueTableWinRate } from '../utils/blueTableCalculation';
import { calcProjectSummary } from '../utils/calculations';
import { toSnake } from '../utils/api';
import { useAuth } from '../utils/authContext';



const STAGE_OPTIONS = ['信息', '线索', '机会', '投标', '议价', '中标'];

const stageColors: Record<string, string> = {

  信息: COLORS.textLight, 线索: COLORS.primary, 机会: COLORS.purple,

  投标: COLORS.warning, 议价: COLORS.amber, 中标: COLORS.success,

};

const statusColors: Record<string, string> = {

  过程中: COLORS.primary, 赢: COLORS.success, 输: COLORS.danger, 冻结: COLORS.textLight,

};

const getWinRateColumn = (tab: string, opp: SalesOpportunity | null, setOpp: (o: SalesOpportunity | null) => void, setOpen: (v: boolean) => void) => {
  if (tab === 'info') return [];
  return [{
    title: '赢率', dataIndex: 'winRate', width: 30, align: 'center' as const,
    filters: ['__all__', [0, 25], [26, 50], [51, 75], [76, 100]].map(r => ({
      text: r === '__all__' ? '全部' : `${r[0]}-${r[1]}%`,
      value: r,
    })),
    filterSearch: true,
    filterDropdownProps: { minOverlayWidthMatchTrigger: false },
    onFilter: (value: unknown, record: SalesOpportunity) => {
      if (value === '__all__') return true;
      const range = value as number[];
      return record.winRate >= range[0] && record.winRate <= range[1];
    },
    render: (v: number, rec: SalesOpportunity) => {
      if (rec.promoteLocked) {
        return <span style={{ color: COLORS.textLight, fontWeight: 600, fontSize: 13 }}>{v}%</span>;
      }
      if (rec.terminated) {
        return <span style={{ cursor: 'pointer', color: COLORS.textLight, fontWeight: 600, fontSize: 13 }}
          onClick={() => { setOpp(rec); setOpen(true); }} title="查看蓝表（只读）">{v}%</span>;
      }
      if (rec.stage === '中标') {
        return <span style={{ color: COLORS.success, fontWeight: 600, fontSize: 13 }}>{v}%</span>;
      }
      const hasBlueTable = !!rec.blueTable;
      if (rec.stage === '线索' && !hasBlueTable) {
        return <span style={{ cursor: 'pointer', color: COLORS.chartGray, fontWeight: 600, fontSize: 13 }} onClick={() => { setOpp(rec); setOpen(true); }} title="点击填写销售蓝表">—</span>;
      }
      if (rec.stage === '信息') {
        return <span style={{ color: COLORS.textLight, fontSize: 13 }}>—</span>;
      }
      const displayVal = hasBlueTable ? rec.winRate : 0;
      return <span style={{ cursor: 'pointer', color: hasBlueTable ? COLORS.primary : COLORS.chartGray, fontWeight: 600, fontSize: 13 }}
        onClick={() => { setOpp(rec); setOpen(true); }}
        title={hasBlueTable ? `蓝表评估：${rec.winRate}%（点击编辑）` : '点击填写销售蓝表'}>{displayVal}%</span>;
    },
  }];
};

const CELL_INPUT: React.CSSProperties = {
  width: '100%', border: 'none', background: 'transparent', outline: 'none',
  fontSize: 13, color: COLORS.textPrimary, padding: '2px 0',
};


// SalesOpportunity state loaded from API; shared with Dashboard/SalesAnalysis via API



const SalesOpportunityList: React.FC = () => {

  const navigate = useNavigate();

  const [msg, ctx] = message.useMessage();

  const { user } = useAuth();

  const [opportunities, setOpportunities] = useState<SalesOpportunity[]>([]);
  const [loading, setLoading] = useState(false);


  const loadOpportunities = useCallback(async () => {
    setLoading(true);
    try {
      const data = await opportunityService.list();
      setOpportunities(data || []);
    } catch { setOpportunities([]); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { loadOpportunities(); }, [loadOpportunities]);
  useEffect(() => {
    clientService.list().then(data => {
      if (data) setEnterpriseClients(data.filter((c: any) => c.type === 'enterprise'));
    }).catch(() => {});
  }, []);

  const currentFy = useMemo(() => {
    const d = new Date(); const y = d.getFullYear(); const m = d.getMonth();
    const y1 = m >= 6 ? y : y - 1; const y2 = m >= 6 ? y + 1 : y;
    return `FY${String(y1 % 100).padStart(2, '0')}${String(y2 % 100).padStart(2, '0')}` as const;
  }, []);
  // ⚠️ 从 URL 参数 ?tab= 初始化标签页（审批管理页面跳转时传入），默认机会
  const initTab = (new URLSearchParams(window.location.search).get('tab') || 'opp') as 'info' | 'lead' | 'opp';
  const [tabFilter, setTabFilter] = useState<'info' | 'lead' | 'opp'>(initTab);
  const [fySelect, setFySelect] = useState(currentFy);
  const [showTerminated, setShowTerminated] = useState(false);



  // Edit modal state

  const [modalOpen, setModalOpen] = useState(false);

  const [editing, setEditing] = useState<SalesOpportunity | null>(null);

  const [formData, setFormData] = useState<Partial<SalesOpportunity>>({});


  // ── 确认弹窗 ──
  const [enterpriseClients, setEnterpriseClients] = useState<Array<{ name: string; salesman: string }>>([]);
  const [deliveryOpp, setDeliveryOpp] = useState<SalesOpportunity | null>(null);
  const [noBlueTableOpp, setNoBlueTableOpp] = useState<SalesOpportunity | null>(null);
  const [terminateOpp, setTerminateOpp] = useState<SalesOpportunity | null>(null);
  const [promoteOpp, setPromoteOpp] = useState<{ opp: SalesOpportunity; targetStage: string } | null>(null);

  const [noBlueTableWarning, setNoBlueTableWarning] = useState(false);

  // ── 阶段晋升弹窗 ──
  const [stagePromote, setStagePromote] = useState<{ opp: SalesOpportunity; nextStage: string } | null>(null);

  // ── 蓝表弹窗 ──
  const [blueTableOpp, setBlueTableOpp] = useState<SalesOpportunity | null>(null);
  const [blueTableOpen, setBlueTableOpen] = useState(false);

  // ── 原因选择弹窗 ──
  const [reasonModal, setReasonModal] = useState<{
    open: boolean; opp: SalesOpportunity | null;
    action: 'win' | 'loss' | 'freeze' | null;
    selectedGroup: string; selections: Record<string, string[]>;
    comment: string; winner: string; dropdownOpen: boolean;
  }>({
    open: false, opp: null, action: null,
    selectedGroup: '', selections: {}, comment: '', winner: '', dropdownOpen: false,
  });


  const now = () => new Date().toISOString();

  const touch = useCallback((id: string, updates: Partial<SalesOpportunity>) => {
    // ⚠️ promoteLocked/terminated 检查：移除后锁定状态下仍可通过 touch 编辑单元格，数据不一致
    setOpportunities(prev => prev.map(o => o.id === id && !o.terminated && !o.promoteLocked ? { ...o, ...updates, updatedAt: now() } : o));
    // ⚠️ opportunityService.update() 不可省略，否则编辑后刷新丢失；keepalive 确保页面卸载前请求完成
    if (!updates.promoteLocked) {
      opportunityService.update(id, updates).catch(err => {
        console.warn('[touch] Save failed for', id, updates, err);
        msg.error('保存失败，请重试');
      });
    }
  }, [msg]);



  const filtered = useMemo(() => {
    const fyRange = parseFY(fySelect);
    // 未来财年不显示任何数据
    if (fyRange.start > new Date()) return [];

    return opportunities.filter(o => {

      if (tabFilter === 'info' && o.stage !== '信息') return false;

      if (tabFilter === 'lead' && o.stage !== '线索') return false;

      if (tabFilter === 'opp' && (o.stage === '信息' || o.stage === '线索')) return false;

      if (!showTerminated && o.terminated) return false;

      // 财年过滤：项目中/冻结视为持续到现在，其余以 updatedAt 为终止时间
      const created = new Date(o.createdAt);
      const effectiveEnd = (o.status === '过程中' || o.status === '冻结')
        ? new Date()
        : new Date(o.updatedAt);
      if (created > fyRange.end || effectiveEnd < fyRange.start) return false;

      return true;

    });

  }, [opportunities, tabFilter, fySelect, showTerminated]);



  const handleStageClick = useCallback((opp: SalesOpportunity) => {
    if (opp.stage === '信息' || opp.stage === '线索') return;
    const idx = STAGE_OPTIONS.indexOf(opp.stage);
    const defaultNext = idx < STAGE_OPTIONS.length - 1 ? STAGE_OPTIONS[idx + 1] : opp.stage;
    setStagePromote({ opp, nextStage: defaultNext });
  }, []);

  const confirmStagePromote = useCallback(() => {
    if (!stagePromote) return;
    const { opp, nextStage } = stagePromote;
    // 中标/赢解耦：仅改阶段，不碰 status/winRate
    const updates: Partial<SalesOpportunity> = { stage: nextStage, updatedAt: now() };
    setOpportunities(prev => prev.map(o => o.id === opp.id && !o.terminated ? { ...o, ...updates } : o));
    opportunityService.update(opp.id, updates as any).catch(err =>
      console.warn('[stage] Promote failed', err)
    );
    setStagePromote(null);
  }, [stagePromote]);



  const openReasonModal = (opp: SalesOpportunity, action: 'win' | 'loss' | 'freeze') => {
    const cfg = REASON_TAXONOMY[action];
    const defaultGroup = cfg.groups[0]?.groupLabel || '';
    // 赢家优先取已保存的 winner 字段，其次从竞争对手列表推断
    const competitors = (opp.competitor || '').split(/[、，]/).map(s => s.trim()).filter(Boolean);
    const winner = opp.winner || (competitors.length === 1 ? competitors[0] : '');
    setReasonModal({ open: true, opp, action, selectedGroup: defaultGroup, selections: {}, comment: '', winner, dropdownOpen: false });
  };

  // ⚠️ 状态变更持久化：必须调用 opportunityService.update() 写入后端，否则刷新后状态回滚
  const handleReasonOk = () => {
    const { opp, action, selectedGroup, selections } = reasonModal;
    if (!opp || !action) return;
    const selList = Object.entries(selections).map(([subLabel, detailItems]) => ({ subLabel, detailItems }));
    const reasonsStr = formatReasons(selectedGroup, selList);
    const updates: Record<string, any> = {
      status: action === 'win' ? '赢' : action === 'loss' ? '输' : '冻结',
      reasons: reasonsStr,
      notes: reasonModal.comment || '',
      updatedAt: now(),
    };
    // ⚠️ winRate/competitor 一律不清理——winRate 来自蓝表计算，competitor 来自用户手动维护
    if (action === 'win') {
      updates.stage = '中标';
      if (opp.status === '输') updates.winner = '';
    }
    if (action === 'loss') {
      // ⚠️ winner 写入独立字段，不覆盖 competitor（竞争对手列表）
      if (reasonModal.winner) updates.winner = reasonModal.winner;
    }
    setOpportunities(prev => prev.map(o => o.id === opp.id ? { ...o, ...updates } : o));
    opportunityService.update(opp.id, updates as any).catch(err =>
      console.warn('[status] Save failed', err)
    );
    setReasonModal(p => ({ ...p, open: false }));
    msg.success('状态已更新');
  };

  const toggleSub = (subLabel: string, detailItems?: string[]) => {
    setReasonModal(prev => {
      const s = { ...prev.selections };
      if (s[subLabel]) { delete s[subLabel]; } else { s[subLabel] = detailItems || []; }
      return { ...prev, selections: s };
    });
  };

  const toggleDetail = (subLabel: string, item: string) => {
    setReasonModal(prev => {
      const s = { ...prev.selections };
      const arr = [...(s[subLabel] || [])];
      const idx = arr.indexOf(item);
      if (idx >= 0) arr.splice(idx, 1); else arr.push(item);
      s[subLabel] = arr;
      return { ...prev, selections: s };
    });
  };

  // ⚠️ 状态恢复为过程中：必须持久化到后端（否则刷新后回滚），不碰 winRate/competitor
  const handleStatusAction = useCallback((opp: SalesOpportunity, action: 'win' | 'loss' | 'freeze' | 'reactivate') => {
    if (action === 'reactivate' || (action === 'freeze' && opp.status === '冻结')) {
      const updates: Record<string, any> = {
        status: '过程中', reasons: '', updatedAt: now(),
      };
      if (opp.status === '输') updates.winner = '';
      setOpportunities(prev => prev.map(o => o.id === opp.id ? { ...o, ...updates } : o));
      opportunityService.update(opp.id, updates).catch(err =>
        console.warn('[status] Restore failed', err)
      );
        msg.success('已恢复为过程中');
      return;
    }
    openReasonModal(opp, action);
  }, [msg]);



  // ── 蓝表保存 ──
  const handleBlueTableSave = useCallback((blueTable: BlueTable) => {
    if (!blueTableOpp) return;
    const calc = calcBlueTableWinRate(blueTable);
    const winRate = calc.finalRate;
    const updates: Partial<SalesOpportunity> = {
      blueTable,
      winRate,
      updatedAt: now(),
    };
    setOpportunities(prev => prev.map(o => o.id === blueTableOpp.id && !o.promoteLocked ? { ...o, ...updates } : o));
    // 持久化蓝表到后端（camelCase → snake_case）
    const rolesSnake = (blueTable.roles || []).map(r => toSnake(r as any));
    opportunityService.saveBlueTable(blueTableOpp.id, {
      ...toSnake(blueTable as any),
      roles: rolesSnake,
    } as any).catch(err => console.warn('[BlueTable] Save failed', err));
    // 同时持久化赢率到机会表
    opportunityService.update(blueTableOpp.id, { winRate } as any)
      .catch(err => console.warn('[BlueTable] winRate save failed', err));
    setBlueTableOpen(false);
    setBlueTableOpp(null);
    msg.success(`蓝表已保存，赢率 ${winRate}%`);
  }, [blueTableOpp, msg]);

  const handleWinDeliver = useCallback((opp: SalesOpportunity) => {
    setDeliveryOpp(opp);
  }, []);

  // ⚠️ 转交付：机会永不从列表移除（terminated=true 后由 showTerminated 过滤控制可见性）
  // 执行顺序：先创建交付，成功后修改机会状态
  const confirmDeliver = useCallback(async () => {
    const opp = deliveryOpp;
    if (!opp) return;
    setDeliveryOpp(null);
    try {
      // 1. 获取已通过审批的最新报价
      let bestQuoteId = opp.quotationId || '';
      try {
        const quotes = await quotationService.list();
        const approved = quotes.filter(q => q.opportunityId === opp.id && q.status === 'approved');
        const best = approved.length > 0 ? approved.reduce((a, b) => {
          const va = parseFloat(a.versionNo.replace('V', ''));
          const vb = parseFloat(b.versionNo.replace('V', ''));
          return vb > va ? b : a;
        }) : null;
        if (best) bestQuoteId = best.id;
      } catch (e) {
        console.warn('[confirmDeliver] 获取报价数据失败', e);
      }

      // 2. 先创建交付项目（成功后才标记机会，避免创建失败但机会已被终止）
      const NODE_NAMES = [
        'Handover', '合同签订', 'Kickoff', '方案细化', '技术会签',
        '详细设计', '设计评审', '制造采购', '组装调试', '出厂验收',
        '包装发货', '现场安调', '验收整改', '终验收', '项目总结',
      ];
      const startDate = new Date();
      // ⚠️ 节点必须包含 name（后端 INSERT 的 name 列 NOT NULL），不传 id（后端自动生成）
      const nodes: DeliveryNode[] = NODE_NAMES.map((name, i) => {
        const ps = new Date(startDate);
        ps.setDate(ps.getDate() + i * 14);
        const pe = new Date(ps);
        pe.setDate(pe.getDate() + (name === '制造采购' ? 28 : 10));
        return {
          nodeNo: i + 1, name, status: 'pending' as const,
          plannedStartDate: ps.toISOString().slice(0, 10),
          plannedEndDate: pe.toISOString().slice(0, 10),
          comments: '', history: [],
        };
      });

      // ⚠️ delivery_projects 表无 nodes 列，创建时不能传 nodes
      const createdDel = await deliveryService.create({
        opportunityId: opp.id,
        salesNo: opp.salesNo.replace(/-S$/, "-E"),
        clientName: opp.clientName,
        projectName: opp.projectName,
        contractAmount: opp.amount,
        quotationId: bestQuoteId,
        status: '进行中',
        planStatus: 'draft',
        costStatus: 'draft',
      } as any);

      if (createdDel?.id) {
        await deliveryService.saveNodes(createdDel.id, nodes);
      }

      // 3. 创建成功后锁定机会和报价（terminated=true 保留历史数据）
      await opportunityService.update(opp.id, { terminated: true } as any).catch(e =>
        console.warn('[confirmDeliver] 标记终止失败', e)
      );
      if (bestQuoteId) {
        await quotationService.update(bestQuoteId, { locked: true } as any).catch(e =>
          console.warn('[confirmDeliver] 锁定报价失败', e)
        );
      }

      msg.success('已转交付');
      navigate('/delivery');
    } catch (err: any) {
      console.error('[confirmDeliver] 转交付失败', err);
      msg.error('转交付失败：' + (err.message || '未知错误'));
    }
  }, [deliveryOpp, msg, navigate]);

  const handlePromote = useCallback((opp: SalesOpportunity, targetStage: string) => {
    // 线索→机会必须填写蓝表
    if (targetStage === '机会' && (!opp.blueTable || opp.blueTable.roles.length === 0)) {
      setNoBlueTableOpp(opp);
      setNoBlueTableWarning(true);
      return;
    }
    setPromoteOpp({ opp, targetStage });
  }, []);

  // ⚠️ 转机会审批：enrichFromProject 不可删除/简化（已因删除导致金额/cost/gp3 全部为 0 共计 3 次）
  // enrichFromProject 从项目组明细实时计算财务汇总，删除/简化会导致金额/cost/gp3 全部为 0（已反复发生 3 次）
  const confirmPromote = useCallback(async () => {
    const po = promoteOpp;
    if (!po) return;
    if (po.targetStage === '机会') {
      let quoteAmount = po.opp.amount || 0;
      let quoteTotalCost = 0;
      let quoteProfitRate = 0;
      let quoteVersionNo = 'V1.0';
      let quoteId = '';
      let tap = 0;      // totalAccountingPrice（预期售价）
      let gp3Val = 0;   // GP3 利润率
      try {
        // 辅助函数：获取对应版本的数据用于审批
        // ⚠️ 优先取 project_version 存储值（否则从组明细重新计算，旧数据无组时取 0 导致审批金额全部错误）
        // 若存储值为 0（旧数据），回退到 calcProjectSummary 按版本过滤组重新计算
        const enrichFromProject = async (projectId: string, fallbackAmount: number, matchVerNo?: string) => {
          try {
            const project = await projectService.getFull(projectId);
            const cv = (matchVerNo ? project.versions?.find(v => v.versionNo === matchVerNo) : null)
              || project.currentVersion
              || project.versions?.[0];
            if (cv) {
              const useStored = cv.totalAccountingPrice > 0 && cv.totalCost > 0;
              if (useStored) {
                tap = cv.totalAccountingPrice || 0;
                quoteTotalCost = cv.totalCost || 0;
                gp3Val = cv.gp3ProfitRate || 0;
                quoteAmount = cv.discountedPrice || fallbackAmount;
                quoteVersionNo = cv.versionNo || quoteVersionNo;
              } else {
                // 存储值为 0，按版本过滤组重新计算（兼容旧数据）
                let versionGroups = project.groups?.filter((g: any) => g.versionId === cv.id) || [];
                if (versionGroups.length === 0) versionGroups = project.groups || [];
                // ⚠️ discountedPrice 已含税，传给 calcProjectSummary 前必须 ÷(1+taxRate) 转未税
                const fbUntaxed = cv.discountedPrice ? Math.round(cv.discountedPrice / (1 + (cv.taxRate || 0.13))) : undefined;
                const summary = calcProjectSummary(versionGroups, cv, fbUntaxed);
                tap = summary.totalAccountingPrice || 0;
                quoteTotalCost = summary.totalCost || 0;
                gp3Val = summary.gp3 || 0;
                quoteAmount = cv.discountedPrice || fallbackAmount;
                quoteVersionNo = cv.versionNo || quoteVersionNo;
              }
              return true;
            }
          } catch (e) {
            console.warn('[enrichFromProject] 获取项目数据失败', projectId, e);
          }
          return false;
        };

        if (po.opp.quotationId) {
          const q = await quotationService.get(po.opp.quotationId);
          if (q) {
            quoteId = q.id;
            quoteAmount = q.amount || quoteAmount;
            quoteTotalCost = q.totalCost || 0;
            quoteProfitRate = q.profitRate || 0;
            quoteVersionNo = q.versionNo || 'V1.0';
            // 用报价的 projectId 获取完整项目数据（enrichFromProject 会覆盖 quoteVersionNo 为版本实际版本号）
            const projectId = (q as any).projectId;
            if (projectId) {
              await enrichFromProject(projectId, quoteAmount, q.versionNo);
            }
          }
        }
        if (!quoteId) {
          // 回退：按 opportunityId 搜索报价列表
          try {
            const quotes = await quotationService.list();
            const match = quotes.find(x => x.opportunityId === po.opp.id);
            if (match) {
              quoteId = match.id;
              quoteAmount = match.amount || quoteAmount;
              quoteTotalCost = match.totalCost || 0;
              quoteProfitRate = match.profitRate || 0;
              quoteVersionNo = match.versionNo || 'V1.0';
              const projectId = (match as any).projectId;
              if (projectId) {
                await enrichFromProject(projectId, quoteAmount, match.versionNo);
              }
            }
          } catch (e) {
            console.warn('[confirmPromote] 回退查询报价列表失败', e);
          }
        }
      } catch (e) {
        console.warn('[confirmPromote] 获取财务数据异常', e);
      }

      const submitterName = user?.displayName || po.opp.salesman || '提交人';

      // 运行时校验：如果关键字段全为 0，说明数据获取有问题，及时报错
      if (quoteAmount <= 0 || (quoteTotalCost <= 0 && gp3Val <= 0)) {
        console.warn('[confirmPromote] 财务数据异常，请检查报价/项目数据', { quoteAmount, quoteTotalCost, gp3Val, tap, quoteVersionNo });
      }

      try {
        await approvalService.create({
          approvalType: 'promote',
          opportunityId: po.opp.id,
          quotationId: quoteId,
          salesNo: po.opp.salesNo,
          clientName: po.opp.clientName,
          projectName: po.opp.projectName,
          amount: quoteAmount,
          totalCost: quoteTotalCost,
          profitRate: quoteProfitRate,
          gp3: gp3Val,
          versionNo: quoteVersionNo,
          totalAccountingPrice: tap || quoteAmount,
          discountedPrice: quoteAmount,
          submitter: submitterName,
          status: 'pending',
        });
        // 锁定机会，待审批完成后再解锁
        await opportunityService.update(po.opp.id, { promoteLocked: true } as any);
        touch(po.opp.id, { promoteLocked: true });
        setPromoteOpp(null);
        msg.success('已提交审批，待总监审批');
      } catch (err) {
        msg.error('提交审批失败：' + ((err as any)?.message || '未知错误'));
      }
    } else {
      touch(po.opp.id, { stage: '线索' });
      setPromoteOpp(null);
      msg.success('已转线索');
    }
  }, [promoteOpp, msg, touch, user]);

  const handleConfirmTerminate = useCallback((opp: SalesOpportunity) => {
    setTerminateOpp(opp);
