    setOpportunities(prev => prev.map(o =>
      o.id === opp.id ? { ...o, terminated: true, updatedAt: now() } : o
    ));
    opportunityService.update(opp.id, { terminated: true } as any).catch(err =>
      console.warn('[terminate] Save failed', err)
    );
    setTerminateOpp(null);
    msg.success('项目已终止');
  }, [terminateOpp, msg]);



