        const t = new Date(v).getTime() + 8 * 3600 * 1000;
        return <span style={{ fontSize: 13, color: COLORS.textLight }}>{new Date(t).toISOString().replace('T', ' ').slice(0, 19)}</span>;
      } },
  ], [tabFilter, touch, handlePromote, handleConfirmTerminate, handleWinDeliver, handleStageClick, opportunities, handleStatusAction, navigate]);



  return (
    <>
      <div>

      {ctx}

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <span style={{ fontSize: 17, fontWeight: 700, color: COLORS.textDark }}>销售管理</span>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <div style={{ marginRight: 32 }}><FYSelector value={fySelect} onChange={setFySelect} /></div>
          <div style={{ display: 'flex', gap: 3, padding: 2, borderRadius: 5, background: COLORS.bgLight, border: `1px solid ${COLORS.borderLight}` }}>
