                background: showTerminated ? COLORS.primary : 'transparent',
                transition: 'all 0.12s',
              }} />
          </div>
        </div>
      </div>



      <div style={{ display: 'flex', gap: 0, marginBottom: 16, borderBottom: `1.5px solid ${COLORS.borderLight}` }}>

