            borderBottom: tabFilter === 'info' ? `2px solid ${COLORS.primary}` : '2px solid transparent',

            color: tabFilter === 'info' ? COLORS.primary : COLORS.textSecondary, fontWeight: tabFilter === 'info' ? 600 : 400,

            marginBottom: -2, transition: 'all 0.15s',

          }}>销售信息

        </div>

        <div onClick={() => { setTabFilter('lead'); window.history.replaceState(null, '', '?tab=lead'); }}

          style={{

            padding: '8px 20px', cursor: 'pointer', fontSize: 14,

            borderBottom: tabFilter === 'lead' ? `2px solid ${COLORS.purple}` : '2px solid transparent',

            color: tabFilter === 'lead' ? COLORS.purple : COLORS.textSecondary, fontWeight: tabFilter === 'lead' ? 600 : 400,

            marginBottom: -2, transition: 'all 0.15s',

          }}>销售线索

        </div>

        <div onClick={() => { setTabFilter('opp'); window.history.replaceState(null, '', '?tab=opp'); }}

          style={{

            padding: '8px 20px', cursor: 'pointer', fontSize: 14,

            borderBottom: tabFilter === 'opp' ? `2px solid ${COLORS.success}` : '2px solid transparent',

            color: tabFilter === 'opp' ? COLORS.success : COLORS.textSecondary, fontWeight: tabFilter === 'opp' ? 600 : 400,

            marginBottom: -2, transition: 'all 0.15s',

          }}>销售机会

        </div>

      </div>
      <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 8 }}>
        <Button type="default" ghost
          onClick={() => openCreateModal(tabFilter === 'info' ? '信息' : tabFilter === 'lead' ? '线索' : '投标')}
          style={{
            width: '100%', height: 48, borderRadius: 10,
            border: `1.5px dashed ${COLORS.borderLight}`,
            color: COLORS.primary, fontSize: 14, fontWeight: 600,
            transition: 'all 0.2s',
          }}
          onMouseEnter={e => { e.currentTarget.style.border = `1.5px dashed ${COLORS.primary}`; e.currentTarget.style.background = COLORS.bgSelected; }}
          onMouseLeave={e => { e.currentTarget.style.border = `1.5px dashed ${COLORS.borderLight}`; e.currentTarget.style.background = 'transparent'; }}
        >
          <PlusOutlined /> 新增{tabFilter === 'info' ? '信息' : tabFilter === 'lead' ? '线索' : '机会'}
        </Button>
      </div>



      <div style={{
        borderRadius: 10, border: `1px solid ${COLORS.borderLight}`,
        boxShadow: '0 2px 8px rgba(0,0,0,0.04)', overflow: 'hidden',
      }}>
      <Table
        dataSource={filtered}
        columns={columns}
        rowKey="id"
        pagination={false}
        size="small"
        bordered
        locale={{ emptyText: '暂无匹配的销售机会' }}
        style={{ background: '#fff', borderRadius: 8 }}
      />
      </div>

      <div style={{
        display: 'flex', gap: 24, marginTop: 12, padding: '10px 16px',
        background: COLORS.bgLight, borderRadius: 4, border: `1px solid ${COLORS.border}`,
        fontSize: 13,
      }}>

        <div style={{ flex: 1 }} />
        <div style={{ fontSize: 12, color: COLORS.textDisabled }}>
          {filtered.length} 个项目
        </div>
      </div>

      {/* 新建/编辑 Modal */}

      <Modal

        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>{editing ? '编辑销售机会' : '新建销售机会'}</span>}

        open={modalOpen}

        onCancel={() => setModalOpen(false)}
        width={520}
        destroyOnHidden
        styles={{ body: { padding: '24px 28px 8px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setModalOpen(false)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={handleModalOk}
              style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }

      >

        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>

          <div style={{ display: 'flex', gap: 12 }}>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>客户名称 *</div>

              <Select showSearch value={formData.clientName || undefined}
                onChange={val => setFormData(p => ({ ...p, clientName: val }))}
                placeholder="搜索选择客户…"
                filterOption={(input, option) =>
                  (option?.label as string || '').toLowerCase().includes(input.toLowerCase())
                }
                notFoundContent={
                  <div style={{ padding: 8, fontSize: 12, color: COLORS.textLight }}>
                    未找到，请先到
                    <a href="/clients" onClick={e => { e.preventDefault(); navigate('/clients'); }}
                      style={{ color: COLORS.primary }}> 客户管理</a>
                    创建
                  </div>
                }
                options={enterpriseClients.filter(c => c.type === 'enterprise').map(c => ({
                  value: c.name, label: c.name,
                }))}
                style={{ width: '100%' }}
              />

            </div>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>项目名称 *</div>

              <Input value={formData.projectName} onChange={e => setFormData(p => ({ ...p, projectName: e.target.value }))} />

            </div>

          </div>

          <div style={{ display: 'flex', gap: 12 }}>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>预计金额</div>

              <Input type="number" value={formData.amount} onChange={e => setFormData(p => ({ ...p, amount: parseInt(e.target.value, 10) || 0 }))} />

            </div>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>项目阶段</div>

              <Select value={formData.stage} onChange={v => setFormData(p => ({ ...p, stage: v }))}

                options={STAGE_OPTIONS.map(s => ({ value: s, label: s }))} style={{ width: '100%' }} />

            </div>

          </div>

          <div style={{ display: 'flex', gap: 12 }}>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>赢率 (%)</div>

              <Input type="number" min={0} max={100} value={formData.winRate} onChange={e => setFormData(p => ({ ...p, winRate: parseInt(e.target.value, 10) || 0 }))} />

            </div>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>竞争对手</div>

              <Input value={formData.competitor} onChange={e => setFormData(p => ({ ...p, competitor: e.target.value }))} placeholder="主要竞争对手" />

            </div>

          </div>

          <div style={{ display: 'flex', gap: 12 }}>

            <div style={{ flex: 1 }}>

              <div style={labelStyle}>区域销售</div>

              <Input value={formData.salesman} onChange={e => setFormData(p => ({ ...p, salesman: e.target.value }))} />

            </div>

          </div>

          <div>

            <div style={labelStyle}>预计定标日期</div>

            <Input value={formData.expectedCloseDate} onChange={e => setFormData(p => ({ ...p, expectedCloseDate: e.target.value }))} placeholder="yyyy-mm-dd" />

          </div>

          <div>

            <div style={labelStyle}>备注</div>

            <Input.TextArea rows={2} value={formData.notes} onChange={e => setFormData(p => ({ ...p, notes: e.target.value }))} />

          </div>

        </div>

      </Modal>

      {/* 转交付弹窗 */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>转交付</span>}
        open={!!deliveryOpp}
        onCancel={() => setDeliveryOpp(null)}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: '14px 32px 6px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setDeliveryOpp(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={confirmDeliver}
              style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        {deliveryOpp && (
          <div style={{ textAlign: 'center', padding: '4px 0 0' }}>
            <div style={{ fontSize: 14, color: COLORS.textDark, fontWeight: 600, marginBottom: 6 }}>
              将"{deliveryOpp.projectName}"转为交付项目？
            </div>
            <div style={{ fontSize: 13, color: COLORS.textMuted, lineHeight: 1.6 }}>
              项目状态将标记为转交付，信息转入交付管理和销售分析。
            </div>
          </div>
        )}
      </Modal>

      {/* 确认终止弹窗 */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>确认终止</span>}
        open={!!terminateOpp}
        onCancel={() => setTerminateOpp(null)}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: "14px 32px 6px" } }}
        footer={
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setTerminateOpp(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={confirmTerminate}
              style={{ borderColor: COLORS.danger, color: COLORS.danger, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        {terminateOpp && (
          <div style={{ textAlign: 'center', padding: '4px 0 0' }}>
            <div style={{ fontSize: 14, color: COLORS.textDark, fontWeight: 600, marginBottom: 6 }}>
              项目"{terminateOpp.projectName}"终止后将不可再修改。
            </div>
            <div style={{ fontSize: 13, color: COLORS.textMuted }}>确认终止？</div>
          </div>
        )}
      </Modal>

      {/* 阶段晋升弹窗（转线索/转机会） */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>{promoteOpp ? (promoteOpp.targetStage === "线索" ? "转线索" : "转机会") : ""}</span>}
        open={!!promoteOpp}
        onCancel={() => setPromoteOpp(null)}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: "14px 32px 6px" } }}
        footer={
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setPromoteOpp(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={confirmPromote}
              style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        {promoteOpp && (
          <div style={{ textAlign: 'center', padding: '4px 0 0' }}>
            <div style={{ fontSize: 14, color: COLORS.textDark, fontWeight: 600, marginBottom: 6 }}>
              {promoteOpp.targetStage === "线索"
                ? '将"' + promoteOpp.opp.projectName + '"转线索？'
                : '将"' + promoteOpp.opp.projectName + '"转机会，提交审批确认？'}
            </div>
            <div style={{ fontSize: 13, color: COLORS.textMuted, lineHeight: 1.6 }}>
              {promoteOpp.targetStage === "机会"
                ? '提交后将进入审批流程，待总监审批通过后晋升为机会。'
                : '确认后直接转为线索阶段。'}
            </div>
          </div>
        )}
      </Modal>

      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>选择阶段</span>}
        open={!!stagePromote}
        onCancel={() => setStagePromote(null)}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: "12px 24px 4px" }, content: { borderRadius: 4 } }}
        footer={
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setStagePromote(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={confirmStagePromote}
              style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        {stagePromote && (
          <div style={{ padding: '4px 0 0' }}>
            <div style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 12, textAlign: 'center' }}>
              「{stagePromote.opp.projectName}」当前阶段：<strong>{stagePromote.opp.stage}</strong>
            </div>
            <div style={{ display: 'flex', gap: 6, justifyContent: 'center', flexWrap: 'wrap' }}>
              {STAGE_OPTIONS.filter(s => s !== '信息' && s !== '线索').map(s => (
                <div key={s} onClick={() => setStagePromote(prev => prev ? { ...prev, nextStage: s } : prev)}
                  style={{
                    padding: '6px 16px', borderRadius: 6, cursor: 'pointer', fontSize: 14,
                    fontWeight: s === stagePromote.nextStage ? 700 : 400,
                    background: s === stagePromote.nextStage ? COLORS.primary : COLORS.bgLight,
                    color: s === stagePromote.nextStage ? '#fff' : COLORS.textPrimary,
                    border: s === stagePromote.opp.stage ? `2px solid ${COLORS.primary}` : `1px solid ${COLORS.borderLight}`,
                    opacity: s === stagePromote.opp.stage ? 0.7 : 1,
                    transition: 'all 0.12s',
                  }}>{s}</div>
              ))}
            </div>
          </div>
        )}
      </Modal>

      {/* 原因选择弹窗 */}

      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>{reasonModal.action === 'loss' ? '输单原因' : reasonModal.action === 'win' ? '赢单原因' : '冻结原因'}</span>}
        open={reasonModal.open}
        onCancel={() => setReasonModal(p => ({ ...p, open: false }))}
        width={420}
        destroyOnHidden
        styles={{ body: { padding: '24px 8px 8px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setReasonModal(p => ({ ...p, open: false }))}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={handleReasonOk}
              style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        {reasonModal.action && reasonModal.opp && (() => {
          const cfg = REASON_TAXONOMY[reasonModal.action];
          const groups = cfg.groups;
          return (
            <div>
              {/* 大类切换标签（下划线样式） */}
              {groups.length > 1 && (
                <div style={{ display: 'flex', gap: 0, marginBottom: 14, borderBottom: `1.5px solid ${COLORS.borderLight}` }}>
                  {groups.map(g => (
                    <span key={g.groupLabel}
                      onClick={() => setReasonModal(p => ({ ...p, selectedGroup: g.groupLabel, selections: {} }))}
                      style={{
                        padding: '6px 18px', fontSize: 13, cursor: 'pointer',
                        borderBottom: reasonModal.selectedGroup === g.groupLabel ? `2px solid ${COLORS.primary}` : '2px solid transparent',
                        color: reasonModal.selectedGroup === g.groupLabel ? COLORS.primary : COLORS.textSecondary,
                        fontWeight: 600,
                        marginBottom: -2, transition: 'all 0.15s',
                      }}
                    >{g.groupLabel}</span>
                  ))}
                </div>
              )}
              {/* 输单时选择赢家（自定义下拉） */}
              {reasonModal.action === 'loss' && reasonModal.opp && reasonModal.opp.competitor && (() => {
                const competitors = reasonModal.opp.competitor.split(/[、，]/).map(s => s.trim()).filter(Boolean);
                if (competitors.length === 0) return null;
                const current = reasonModal.winner || competitors[0];
                return (
                  <div style={{ marginBottom: 12, display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontSize: 13, color: '#444', fontWeight: 600 }}>赢家</span>
                    <div style={{ position: 'relative' }}>
                      <div onClick={() => setReasonModal(p => ({ ...p, dropdownOpen: !p.dropdownOpen }))}
                        style={{
                          fontSize: 13, padding: '4px 8px', borderRadius: 4,
                          background: COLORS.bgLight, color: COLORS.primary, cursor: 'pointer',
                          minWidth: 100, userSelect: 'none', position: 'relative',
                        }}
                      >
                        {current}
                        <span style={{ position: 'absolute', right: 6, top: '50%', transform: 'translateY(-50%)', fontSize: 10, color: COLORS.primary }}>▼</span>
                      </div>
                      {reasonModal.dropdownOpen && (
                        <div style={{
                          position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 10,
                          background: COLORS.bgLight, marginTop: 2, borderRadius: 4,
                          overflow: 'hidden',
                        }}>
                          {competitors.map(c => (
                            <div key={c}
                              onClick={() => { setReasonModal(p => ({ ...p, winner: c, dropdownOpen: false })); }}
                              style={{
                                padding: '4px 8px', fontSize: 13, color: current === c ? COLORS.primary : '#555',
                                background: current === c ? '#c8e6c9' : 'transparent',
                                cursor: 'pointer', fontWeight: current === c ? 600 : 400,
                              }}
                            >
                              {c}
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })()}
              {/* 选中大类下的原因列表（平铺） */}
              {(() => {
                const activeGroup = groups.find(g => g.groupLabel === reasonModal.selectedGroup);
                if (!activeGroup) return null;
                const items = activeGroup.items;
                return (
                  <div style={{ height: 280, overflowY: 'auto' }}>
                    {items.map(item => {
                      const hasSub = item.items && item.items.length > 0;
                      if (!hasSub) {
                        const checked = reasonModal.selections[item.label] !== undefined;
                        return (
                          <div key={item.label} onClick={() => toggleSub(item.label)}
                            style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', padding: '5px 10px', borderRadius: 5, marginBottom: 2, background: checked ? '#eef4ff' : '#f8f8f8', border: '1px solid ' + (checked ? COLORS.primary : COLORS.border) }}
                          >
                            <span style={{ width: 15, height: 15, borderRadius: 3, border: '1.5px solid ' + (checked ? COLORS.primary : COLORS.textDisabled), display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, color: checked ? '#fff' : 'transparent', background: checked ? COLORS.primary : 'transparent', fontWeight: 700, flexShrink: 0 }}>
                              {checked ? '✓' : ''}
                            </span>
                            <span style={{ fontSize: 13, color: checked ? COLORS.primary : '#444' }}>{item.label}</span>
                          </div>
                        );
                      }
                      return (
                        <div key={item.label} style={{ marginBottom: 4 }}>
                          <div style={{ fontSize: 13, fontWeight: 400, color: '#444', marginBottom: 3, padding: '2px 0' }}>{item.label}</div>
                          <div style={{ display: 'flex', flexDirection: 'column', gap: 3, marginLeft: 4 }}>
                            {item.items!.map(subItem => {
                              const dc = (reasonModal.selections[item.label] || []).includes(subItem.label);
                              return (
                                <div key={subItem.label} onClick={() => toggleDetail(item.label, subItem.label)}
                                  style={{ display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', padding: '5px 10px', borderRadius: 5, background: dc ? '#eef4ff' : '#f8f8f8', border: '1px solid ' + (dc ? COLORS.primary : COLORS.border) }}
                                >
                                  <span style={{ width: 15, height: 15, borderRadius: 3, border: '1.5px solid ' + (dc ? COLORS.primary : COLORS.textDisabled), display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, color: dc ? '#fff' : 'transparent', background: dc ? COLORS.primary : 'transparent', fontWeight: 700, flexShrink: 0 }}>
                                    {dc ? '✓' : ''}
                                  </span>
                                  <span style={{ fontSize: 13, color: dc ? COLORS.primary : '#444' }}>{subItem.label}</span>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              })()}
              {/* Comment */}
              <div style={{ marginTop: 12, borderTop: '1px solid #eee', paddingTop: 10 }}>
                <textarea
                  value={reasonModal.comment || ''}
                  onChange={e => setReasonModal(p => ({ ...p, comment: e.target.value }))}
                  placeholder="备注说明（选填）"
                  rows={2}
                  style={{
                    width: '100%', boxSizing: 'border-box',
                    fontSize: 13, color: '#444',
                    border: '1px solid #ddd', borderRadius: 6,
                    padding: '6px 10px', resize: 'none', outline: 'none',
                  }}
                />
              </div>
            </div>
          );
        })()}
      </Modal>

      {/* 蓝表缺失提示弹窗 */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>需要先填写销售蓝表</span>}
        open={noBlueTableWarning}
        onCancel={() => setNoBlueTableWarning(false)}
        width={460}
        destroyOnHidden
        styles={{ body: { padding: '14px 32px 6px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setNoBlueTableWarning(false)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} onClick={() => setNoBlueTableWarning(false)}
              style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }}>知道了</Button>
          </div>
        }
      >
        <div style={{ textAlign: 'center', padding: '4px 0 0' }}>
          <div style={{ fontSize: 14, color: COLORS.textDark, fontWeight: 600, marginBottom: 6 }}>
            从线索晋升到机会前，请先完成销售蓝表评估
          </div>
          <div style={{ fontSize: 13, color: COLORS.textMuted, lineHeight: 1.6 }}>
            需要包含至少一个采购角色。
          </div>
        </div>
      </Modal>

      {/* 蓝表弹窗 */}
      <BlueTableModal
        open={blueTableOpen}
        opportunity={blueTableOpp}
        onSave={handleBlueTableSave}
        onClose={() => { setBlueTableOpen(false); setBlueTableOpp(null); }}
        readOnly={!!blueTableOpp?.terminated}
      />

    </div>
    </>
  );
};



const labelStyle: React.CSSProperties = {

  fontSize: 12, fontWeight: 600, color: COLORS.textPrimary, marginBottom: 4,

};



// ── 项目名称下拉搜索器 ──

// ── 客户名称下拉搜索器 ──
export default SalesOpportunityList;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Table, Button, Modal, Input, message, Switch } from 'antd';
import { PlusOutlined, EditOutlined, KeyOutlined, CheckOutlined, CloseOutlined, SettingOutlined, DeleteOutlined } from '@ant-design/icons';
import { COLORS } from '../styles/colors';
import { userService, type UserRecord } from '../services/userService';
import { auditLogService, type AuditLog } from '../services/auditLogService';
import type { TableProps } from 'antd';

/* ============================================================
   角色颜色映射
   ============================================================ */
const LABEL_CELL_STYLE: React.CSSProperties = {
  padding: '7px 12px', fontSize: 12, border: '1px solid #e8e8e8',
  verticalAlign: 'middle', fontWeight: 600, background: '#f7f8fa',
  whiteSpace: 'nowrap', color: '#555',
};

const VAL_CELL_STYLE: React.CSSProperties = {
  padding: '7px 12px', fontSize: 12, border: '1px solid #e8e8e8',
  verticalAlign: 'middle',
};

const INP_STYLE: React.CSSProperties = {
  width: '100%', border: 'none', background: 'transparent', outline: 'none',
  fontSize: 13, padding: '2px 0', margin: 0, display: 'block',
  boxSizing: 'border-box', lineHeight: 1.3,
};

type TabKey = 'users' | 'logs';

const TABS: { key: TabKey; label: string }[] = [
  { key: 'users', label: '用户管理' },
  { key: 'logs', label: '操作日志' },
];

/* ============================================================
   角色权限模板
   ============================================================ */
const ALL_PERMISSIONS = [
  '仪表盘查看', '销售机会管理', '新建信息/线索/机会', '编辑销售机会', '转线索/转机会',
  '销售蓝表编辑', '报价列表查看', '报价编制', '审批管理', '交付管理', '交付分析',
  '成本录入', '物料管理', '新增物料', '新建标签', '客户管理', '新建客户',
  '用户管理', '系统配置', '全部查看权限',
];

const ROLE_PERMISSIONS: Record<string, string[]> = {
  user: ['销售机会管理', '报价列表查看', '销售分析', '客户管理', '仪表盘查看'],
  manager: ['交付管理', '交付分析', '成本录入', '物料管理', '仪表盘查看', '报价列表查看', '销售机会管理', '客户管理'],
  admin: ['审批管理', '用户管理', '系统配置', '全部查看权限', '仪表盘查看', '销售机会管理', '报价编制', '物料管理', '交付管理', '客户管理'],
  director: ['审批管理', '用户管理', '系统配置', '全部查看权限', '仪表盘查看', '销售机会管理', '报价编制', '物料管理', '交付管理', '客户管理', '新增物料', '新建标签', '新建客户', '新建信息/线索/机会', '编辑销售机会', '转线索/转机会', '销售蓝表编辑', '交付分析', '成本录入'],
};

/* ============================================================
   Component
   ============================================================ */
const SystemManagement: React.FC = () => {
  const [tab, setTab] = useState<TabKey>('users');
  const [messageApi, msgContextHolder] = message.useMessage();

  // 用户数据
  const [users, setUsers] = useState<UserRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const data = await userService.list();
      setUsers(data);
    } catch (err: any) {
      messageApi.error('加载用户列表失败：' + (err.message || '未知错误'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  // 弹窗状态
  const [addOpen, setAddOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [pwdOpen, setPwdOpen] = useState(false);
  const [permOpen, setPermOpen] = useState(false);
  const [editTarget, setEditTarget] = useState<UserRecord | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<UserRecord | null>(null);

  // 新增用户表单
  const [newName, setNewName] = useState('');
  const [newRole, setNewRole] = useState('user');
  const [newTitle, setNewTitle] = useState('销售经理');
  const [newPhone, setNewPhone] = useState('');
  const [newEmail, setNewEmail] = useState('');

  // 编辑用户表单
  const [editName, setEditName] = useState('');
  const [editTitle, setEditTitle] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editEmail, setEditEmail] = useState('');

  // 密码重置
  const [resetPwd, setResetPwd] = useState('');
  const [confirmPwd, setConfirmPwd] = useState('');

  // 角色权限
  const [permRole, setPermRole] = useState('user');
  const [permTitle, setPermTitle] = useState('');
  const [checkedPerms, setCheckedPerms] = useState<string[]>([]);

  // 操作日志
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [logLoading, setLogLoading] = useState(false);
  const [logModuleFilter, setLogModuleFilter] = useState<string | null>(null);

  const loadLogs = useCallback(async () => {
    setLogLoading(true);
    try {
      const data = await auditLogService.list();
      setLogs(data);
    } catch {
      messageApi.error('加载操作日志失败');
    } finally {
      setLogLoading(false);
    }
  }, [messageApi]);

  useEffect(() => {
    if (tab === 'logs') loadLogs();
  }, [tab, loadLogs]);

  /* ---- 用户管理操作 ---- */

  const toggleUserActive = async (user: UserRecord) => {
    try {
      const updated = await userService.update(user.id, { isActive: !user.isActive });
      setUsers(prev => prev.map(u => u.id === updated.id ? updated : u));
    } catch (err: any) {
      messageApi.error('操作失败：' + (err.message || ''));
    }
  };

  const openAddModal = () => {
    setNewName(''); setNewRole('user'); setNewTitle('销售经理');
    setNewPhone(''); setNewEmail('');
    setAddOpen(true);
  };

  const handleAddUser = async () => {
    if (!newName.trim()) { messageApi.warning('请输入用户姓名'); return; }
    if (!newEmail.trim()) { messageApi.warning('请输入邮箱'); return; }

    setSaving(true);
    try {
      const created = await userService.create({
        email: newEmail.trim(),
        displayName: newName.trim(),
        title: newTitle,
        phone: newPhone.trim(),
        password: '123456',
        role: newRole,
      });
      setUsers(prev => [...prev, created]);
      setAddOpen(false);
      messageApi.success(`用户 ${created.displayName} 添加成功（初始密码 123456）`);
    } catch (err: any) {
      messageApi.error(err.message || '添加失败');
    } finally {
      setSaving(false);
    }
  };

  const openEditModal = (u: UserRecord) => {
    setEditTarget(u);
    setEditName(u.displayName);
    setEditTitle(u.title);
    setEditPhone(u.phone || '');
    setEditEmail(u.email);
    setEditOpen(true);
  };

  const handleEditSave = async () => {
    if (!editTarget) return;
    if (!editEmail.trim()) { messageApi.warning('邮箱不能为空'); return; }

    setSaving(true);
    try {
      const updated = await userService.update(editTarget.id, {
        displayName: editName.trim(),
        email: editEmail.trim(),
        title: editTitle,
        phone: editPhone.trim(),
      });
      setUsers(prev => prev.map(u => u.id === updated.id ? updated : u));
      setEditOpen(false);
      setEditTarget(null);
      messageApi.success('用户信息已更新');
    } catch (err: any) {
      messageApi.error(err.message || '更新失败');
    } finally {
      setSaving(false);
    }
  };

  const openPwdModal = (u: UserRecord) => {
    setEditTarget(u);
    setResetPwd(''); setConfirmPwd('');
    setPwdOpen(true);
  };

  const handlePwdReset = async () => {
    if (!editTarget) return;
    if (!resetPwd.trim()) { messageApi.warning('请输入新密码'); return; }
    if (resetPwd.length < 6) { messageApi.warning('密码长度不能少于6位'); return; }
    if (resetPwd !== confirmPwd) { messageApi.warning('两次输入的密码不一致'); return; }

    setSaving(true);
    try {
      await userService.resetPassword(editTarget.id, resetPwd);
      setPwdOpen(false);
      setEditTarget(null);
      messageApi.success('密码已重置');
    } catch (err: any) {
      messageApi.error(err.message || '密码重置失败');
    } finally {
      setSaving(false);
    }
  };

  const TITLE_PERMISSIONS: Record<string, string[]> = {
    '销售经理': ['销售机会管理', '新建信息/线索/机会', '编辑销售机会', '转线索/转机会', '销售蓝表编辑', '客户管理', '新建客户', '报价列表查看', '仪表盘查看'],
    '方案经理': ['物料管理', '新增物料', '新建标签', '报价编制', '报价列表查看', '仪表盘查看', '销售机会管理', '客户管理'],
    '交付经理': ['交付管理', '交付分析', '成本录入', '物料管理', '仪表盘查看', '报价列表查看', '销售机会管理', '客户管理'],
    '部门总监': ['全部查看权限', '审批管理', '用户管理', '系统配置', '仪表盘查看', '销售机会管理', '报价编制', '物料管理', '新增物料', '新建标签', '交付管理', '交付分析', '客户管理', '新建客户', '新建信息/线索/机会', '编辑销售机会', '转线索/转机会', '销售蓝表编辑', '成本录入'],
  };

  const openPermModal = (u: UserRecord) => {
    setEditTarget(u);
    setPermRole(u.role);
    setPermTitle(u.title);
    // 优先使用数据库已保存的权限，否则用职务预设
    setCheckedPerms(u.permissions && u.permissions.length > 0
      ? [...u.permissions]
      : [...(TITLE_PERMISSIONS[u.title] || ROLE_PERMISSIONS[u.role] || [])]);
    setPermOpen(true);
  };

  const handlePermSave = async () => {
    if (!editTarget) return;
    setSaving(true);
    try {
      const updated = await userService.updateRole(editTarget.id, permRole, permTitle, checkedPerms);
      setUsers(prev => prev.map(u => u.id === updated.id ? updated : u));
      setPermOpen(false);
      setEditTarget(null);
      messageApi.success('角色权限已更新');
    } catch (err: any) {
      messageApi.error(err.message || '更新失败');
    } finally {
      setSaving(false);
    }
  };

  const confirmDeleteUser = async () => {
    if (!deleteTarget) return;
    setSaving(true);
    try {
      await userService.delete(deleteTarget.id);
      setUsers(prev => prev.filter(u => u.id !== deleteTarget.id));
      setDeleteTarget(null);
      messageApi.success('用户已删除');
    } catch (err: any) {
      messageApi.error(err.message || '删除失败');
    } finally {
      setSaving(false);
    }
  };

  /* ---- 表格列 ---- */
  const userColumns: TableProps<UserRecord>['columns'] = [
    { title: '姓名', dataIndex: 'displayName', key: 'displayName', width: 100 },
    {
      title: '职务', dataIndex: 'title', key: 'title', width: 120,
      render: (v: string) => (
        <span style={{ color: COLORS.textDark, fontWeight: 500 }}>{v || '—'}</span>
      ),
    },
    { title: '电话', dataIndex: 'phone', key: 'phone', width: 150,
      render: (v: string) => <span style={{ color: COLORS.textDark }}>{v || '—'}</span>,
    },
    { title: '邮箱', dataIndex: 'email', key: 'email', width: 230 },
    {
      title: '状态', dataIndex: 'isActive', key: 'isActive', width: 70,
      render: (v: boolean, rec: UserRecord) => (
        <Switch checked={v} size="small" onChange={() => toggleUserActive(rec)}
          style={{ background: v ? COLORS.success : COLORS.borderInput }} />
      ),
    },
    {
      title: '操作', key: 'action', width: 160,
      render: (_: unknown, rec: UserRecord) => (
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          <span onClick={() => openEditModal(rec)}
            style={{ color: COLORS.primary, cursor: 'pointer', fontSize: 13, whiteSpace: 'nowrap' }}>
            <EditOutlined style={{ marginRight: 2 }} />编辑
          </span>
          <span style={{ color: '#d0d0d0' }}>|</span>
          <span onClick={() => openPwdModal(rec)}
            style={{ color: COLORS.warning, cursor: 'pointer', fontSize: 13, whiteSpace: 'nowrap' }}>
            <KeyOutlined style={{ marginRight: 2 }} />密码
          </span>
          <span style={{ color: '#d0d0d0' }}>|</span>
          <span onClick={() => openPermModal(rec)}
            style={{ color: COLORS.purple, cursor: 'pointer', fontSize: 13, whiteSpace: 'nowrap' }}>
            <SettingOutlined style={{ marginRight: 2 }} />权限
          </span>
          <span style={{ color: '#d0d0d0' }}>|</span>
          <span onClick={() => setDeleteTarget(rec)}
            style={{ color: COLORS.danger, cursor: 'pointer', fontSize: 13, whiteSpace: 'nowrap' }}>
            <DeleteOutlined style={{ marginRight: 2 }} />移除
          </span>
        </div>
      ),
    },
  ];

  /* ---- 操作日志 ---- */
  const logModules = useMemo(() => {
    const mods = new Set(logs.map(l => l.module));
    return ['全部', ...Array.from(mods)];
  }, [logs]);

  const filteredLogs = useMemo(() => {
    if (!logModuleFilter || logModuleFilter === '全部') return logs;
    return logs.filter(l => l.module === logModuleFilter);
  }, [logs, logModuleFilter]);

  const logColumns: TableProps<AuditLog>['columns'] = [
    { title: '时间', dataIndex: 'time', key: 'time', width: 160 },
    { title: '操作人', dataIndex: 'userName', key: 'userName', width: 72 },
    { title: '模块', dataIndex: 'module', key: 'module', width: 88 },
    { title: '操作', dataIndex: 'action', key: 'action', width: 88 },
    { title: '详情', dataIndex: 'detail', key: 'detail' },
  ];

  /* ---- 可用角色列表 ---- */
  const ROLE_OPTIONS = [
    { role: 'director', title: '部门总监' },
    { role: 'admin', title: '管理员' },
    { role: 'manager', title: '交付经理' },
    { role: 'user', title: '用户' },
  ];

  return (
    <div>
      {msgContextHolder}

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <span style={{ fontSize: 17, fontWeight: 700, color: COLORS.textDark }}>系统管理</span>
      </div>

      <div style={{ display: 'flex', gap: 0, marginBottom: 20, borderBottom: `2px solid ${COLORS.border}` }}>
        {TABS.map(t => (
          <div key={t.key} onClick={() => setTab(t.key)}
            style={{
              padding: '8px 20px', cursor: 'pointer', fontSize: 14,
              borderBottom: tab === t.key ? `2px solid ${COLORS.primary}` : '2px solid transparent',
              color: tab === t.key ? COLORS.primary : COLORS.textSecondary,
              fontWeight: tab === t.key ? 600 : 400,
              marginBottom: -2, transition: 'all 0.15s', userSelect: 'none',
            }}>{t.label}</div>
        ))}
      </div>

      {/* ================================================================
          用户管理
          ================================================================ */}
      {tab === 'users' && (
        <div>
          <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 12 }}>
            <Button type="default" ghost icon={<PlusOutlined />} onClick={openAddModal}
              style={{
                borderRadius: 8, border: `1.5px dashed ${COLORS.borderLight}`,
                color: COLORS.primary, fontSize: 13, fontWeight: 600, height: 32,
                transition: 'all 0.2s',
              }}
              onMouseEnter={e => { e.currentTarget.style.border = `1.5px dashed ${COLORS.primary}`; e.currentTarget.style.background = COLORS.bgSelected; }}
              onMouseLeave={e => { e.currentTarget.style.border = `1.5px dashed ${COLORS.borderLight}`; e.currentTarget.style.background = 'transparent'; }}
            >新增用户</Button>
          </div>

          <div style={{
            borderRadius: 10, border: `1px solid ${COLORS.borderLight}`,
            boxShadow: '0 2px 8px rgba(0,0,0,0.04)', overflow: 'hidden',
          }}>
          <Table<UserRecord>
            dataSource={users}
            columns={userColumns}
            rowKey="id"
            pagination={false}
            size="small"
            bordered
            loading={loading}
            style={{ fontSize: 13, background: '#fff', borderRadius: 8 }}
          />
          </div>

          {/* ---------- 新增用户弹窗 ---------- */}
          <Modal
            title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark }}>新增用户</span>}
            open={addOpen}
            onCancel={() => setAddOpen(false)}
            width={480}
            destroyOnHidden
            styles={{ body: { padding: '14px 2px 6px' } }}
            footer={
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                <Button icon={<CloseOutlined />} onClick={() => setAddOpen(false)}
                  style={{ borderRadius: 3, width: 36, height: 36 }} />
                <Button type="primary" ghost icon={<CheckOutlined />} loading={saving} onClick={handleAddUser}
                  style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
              </div>
            }
          >

              <table style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed' }}>
                <colgroup>
                  <col width="100" /><col width="*" />
                </colgroup>
                <tbody>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>姓名 <span style={{ color: COLORS.danger }}>*</span></td>
                    <td style={VAL_CELL_STYLE}>
                      <input value={newName} onChange={e => setNewName(e.target.value)}
                        placeholder="输入用户姓名" style={INP_STYLE} />
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>手机号</td>
                    <td style={VAL_CELL_STYLE}>
                      <input value={newPhone} onChange={e => setNewPhone(e.target.value)}
                        placeholder="输入手机号" style={INP_STYLE} />
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>邮箱 *</td>
                    <td style={VAL_CELL_STYLE}>
                      <input value={newEmail} onChange={e => setNewEmail(e.target.value)}
                        placeholder="user@example.com" style={INP_STYLE} />
                      <span style={{ fontSize: 10, color: '#aaa', marginLeft: 4 }}>作为登录账号</span>
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>职务 *</td>
                    <td style={VAL_CELL_STYLE}>
                      <select value={newTitle} onChange={e => setNewTitle(e.target.value)}
                        style={{ width: '100%', border: 'none', background: 'transparent', outline: 'none', fontSize: 13, padding: 0, cursor: 'pointer', color: COLORS.textPrimary }}>
                        <option value="销售经理">销售经理</option>
                        <option value="方案经理">方案经理</option>
                        <option value="交付经理">交付经理</option>
                        <option value="部门总监">部门总监</option>
                      </select>
                    </td>
                  </tr>
                </tbody>
              </table>
              <div style={{ fontSize: 11, color: '#aaa', marginTop: 12, textAlign: 'center' }}>
                💡 新增用户初始密码为 <strong>123456</strong>
              </div>
          </Modal>

          {/* ---------- 编辑用户弹窗 ---------- */}
          <Modal
            title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark }}>编辑用户</span>}
            open={editOpen}
            onCancel={() => { setEditOpen(false); setEditTarget(null); }}
            width={460}
            destroyOnHidden
            styles={{ body: { padding: '14px 2px 6px' } }}
            footer={
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                <Button icon={<CloseOutlined />} onClick={() => { setEditOpen(false); setEditTarget(null); }}
                  style={{ borderRadius: 3, width: 36, height: 36 }} />
                <Button type="primary" ghost icon={<CheckOutlined />} loading={saving} onClick={handleEditSave}
                  style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
              </div>
            }
          >
            {editTarget && (
              <table style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed' }}>
                <colgroup>
                  <col width="100" /><col width="*" />
                </colgroup>
                <tbody>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>姓名</td>
                    <td style={VAL_CELL_STYLE}>
                      <input value={editName} onChange={e => setEditName(e.target.value)} style={INP_STYLE} />
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>手机号</td>
                    <td style={VAL_CELL_STYLE}>
                      <input value={editPhone} onChange={e => setEditPhone(e.target.value)} style={INP_STYLE} />
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>职务</td>
                    <td style={VAL_CELL_STYLE}>
                      <select value={editTitle} onChange={e => setEditTitle(e.target.value)}
                        style={{ width: '100%', border: 'none', background: 'transparent', outline: 'none', fontSize: 13, padding: 0, cursor: 'pointer', color: COLORS.textPrimary }}>
                        <option value="销售经理">销售经理</option>
                        <option value="方案经理">方案经理</option>
                        <option value="交付经理">交付经理</option>
                        <option value="部门总监">部门总监</option>
                      </select>
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>邮箱 *</td>
                    <td style={VAL_CELL_STYLE}>
                      <input value={editEmail} onChange={e => setEditEmail(e.target.value)} style={INP_STYLE} />
                    </td>
                  </tr>
                </tbody>
              </table>
            )}
          </Modal>

          {/* ---------- 密码重置弹窗 ---------- */}
          <Modal
            title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark }}>重置密码</span>}
            open={pwdOpen}
            onCancel={() => { setPwdOpen(false); setEditTarget(null); }}
            width={460}
            destroyOnHidden
            styles={{ body: { padding: '14px 2px 6px' } }}
            footer={
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                <Button icon={<CloseOutlined />} onClick={() => { setPwdOpen(false); setEditTarget(null); }}
                  style={{ borderRadius: 3, width: 36, height: 36 }} />
                <Button type="primary" ghost icon={<CheckOutlined />} loading={saving} onClick={handlePwdReset}
                  style={{ borderColor: COLORS.warning, color: COLORS.warning, borderRadius: 3, width: 36, height: 36 }} />
              </div>
            }
          >
            {editTarget && (
              <><div style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 16 }}>
                用户：<strong style={{ color: COLORS.textDark }}>{editTarget.displayName}</strong>
                <span style={{ color: COLORS.textLight, marginLeft: 8 }}>（{editTarget.email}）</span>
              </div>
              <table style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed' }}>
                <colgroup>
                  <col width="100" /><col width="*" />
                </colgroup>
                <tbody>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>新密码 *</td>
                    <td style={VAL_CELL_STYLE}>
                      <input type="password" value={resetPwd}
                        onChange={e => setResetPwd(e.target.value)}
                        placeholder="输入新密码（至少6位）" style={INP_STYLE} />
                    </td>
                  </tr>
                  <tr>
                    <td style={LABEL_CELL_STYLE}>确认密码 *</td>
                    <td style={VAL_CELL_STYLE}>
                      <input type="password" value={confirmPwd}
                        onChange={e => setConfirmPwd(e.target.value)}
                        placeholder="再次输入新密码" style={INP_STYLE} />
                    </td>
                  </tr>
                </tbody>
              </table>
              </>
              )}
          </Modal>

          {/* ---------- 角色权限配置弹窗 ---------- */}
          <Modal
            title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark }}>角色权限配置</span>}
            open={permOpen}
            onCancel={() => { setPermOpen(false); setEditTarget(null); }}
            width={460}
            destroyOnHidden
            styles={{ body: { padding: '14px 2px 6px' } }}
            footer={
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                <Button icon={<CloseOutlined />} onClick={() => { setPermOpen(false); setEditTarget(null); }}
                  style={{ borderRadius: 3, width: 36, height: 36 }} />
                <Button type="primary" ghost icon={<CheckOutlined />} loading={saving} onClick={handlePermSave}
                  style={{ borderColor: COLORS.primary, color: COLORS.primary, borderRadius: 3, width: 36, height: 36 }} />
              </div>
            }
          >
            {editTarget && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 14, padding: '4px 0 0' }}>
                <div style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 4 }}>
                  用户：<strong style={{ color: COLORS.textDark }}>{editTarget.displayName}</strong>
                </div>
                <div>
                  <div style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 8 }}>职务：</div>
                  <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                    {['销售经理', '方案经理', '交付经理', '部门总监'].map(t => (
                      <div key={t} onClick={() => setPermTitle(t)}
                        style={{
                          padding: '4px 14px', borderRadius: 4, cursor: 'pointer', fontSize: 13,
                          border: `1.5px solid ${permTitle === t ? COLORS.primary : '#d0d0d0'}`,
                          color: permTitle === t ? '#fff' : '#555',
                          background: permTitle === t ? COLORS.primary : '#fff',
                          transition: 'all 0.15s', userSelect: 'none',
                        }}>{t}</div>
                    ))}
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: 13, color: COLORS.textSecondary, marginBottom: 8 }}>权限：</div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {ALL_PERMISSIONS.map(p => (
                      <div key={p}
                        style={{
                          display: 'flex', alignItems: 'center', gap: 8,
                          padding: '6px 10px', borderRadius: 4,
                          background: checkedPerms.includes(p) ? '#f0f6ff' : COLORS.bgLight,
                          cursor: 'pointer', userSelect: 'none',
                        }}
                        onClick={() => {
                          setCheckedPerms(prev =>
                            prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p]
                          );
                        }}
                      >
                        <div style={{
                          width: 16, height: 16, borderRadius: 3, flexShrink: 0,
                          border: `2px solid ${checkedPerms.includes(p) ? COLORS.primary : '#d0d0d0'}`,
                          background: checkedPerms.includes(p) ? COLORS.primary : 'transparent',
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          transition: 'all 0.15s', userSelect: 'none',
                        }}>
                          {checkedPerms.includes(p) && <span style={{ color: '#fff', fontSize: 11, lineHeight: 1 }}>✓</span>}
                        </div>
                        <span style={{ fontSize: 13, color: COLORS.textPrimary }}>{p}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </Modal>

        </div>
      )}

      {/* ================================================================
          操作日志
          ================================================================ */}
      {tab === 'logs' && (
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
            <span style={{ fontSize: 13, color: COLORS.textSecondary }}>模块筛选：</span>
            {logModules.map(m => (
              <div key={m} onClick={() => setLogModuleFilter(m === '全部' ? null : m)}
                style={{
                  padding: '3px 14px', borderRadius: 12, cursor: 'pointer', fontSize: 12,
                  background: (m === '全部' && !logModuleFilter) || logModuleFilter === m ? COLORS.primary : COLORS.borderLight,
                  color: (m === '全部' && !logModuleFilter) || logModuleFilter === m ? '#fff' : COLORS.textPrimary,
                  transition: 'all 0.15s', userSelect: 'none',
                }}>
                {m}
              </div>
            ))}
          </div>

          <div style={{
            borderRadius: 10, border: `1px solid ${COLORS.borderLight}`,
            boxShadow: '0 2px 8px rgba(0,0,0,0.04)', overflow: 'hidden',
          }}>
          <Table<AuditLog>
            dataSource={filteredLogs}
            columns={logColumns}
            pagination={false}
            size="small"
            style={{ fontSize: 13, background: '#fff', borderRadius: 8 }}
          />
          </div>
        </div>
      )}

      {/* 删除确认弹窗 */}
      <Modal
        title={<span style={{ fontSize: 17, fontWeight: 600, color: COLORS.textDark, letterSpacing: 0.5 }}>删除用户</span>}
        open={!!deleteTarget}
        onCancel={() => setDeleteTarget(null)}
        width={420}
        destroyOnHidden
        styles={{ body: { padding: '24px 28px 12px' } }}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <Button icon={<CloseOutlined />} onClick={() => setDeleteTarget(null)}
              style={{ borderRadius: 3, width: 36, height: 36 }} />
            <Button type="primary" ghost icon={<CheckOutlined />} loading={saving} onClick={confirmDeleteUser}
              style={{ borderColor: COLORS.danger, color: COLORS.danger, borderRadius: 3, width: 36, height: 36 }} />
          </div>
        }
      >
        <div style={{ textAlign: 'center', padding: '16px 0' }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>🗑️</div>
          <div style={{ fontSize: 14, color: COLORS.textSecondary }}>确定删除用户「{deleteTarget?.displayName}」吗？</div>
        </div>
      </Modal>

    </div>
  );
};

export default SystemManagement;

import React, { useState, useEffect } from 'react';
import { Button, Modal, Input, message as antMsg, Spin } from 'antd';
import { PlusOutlined, DeleteOutlined, ArrowUpOutlined, ArrowDownOutlined, CheckOutlined, CloseOutlined } from '@ant-design/icons';
import { mockTagTree } from '../mockData';
import type { TagNode } from '../types';
import { COLORS } from '../styles/colors';
import { cloneTree, findPath, getNodeByPath, uid, flattenTree } from '../utils/tagHelpers';
import { tagService } from '../services/tagService';

// ── 组件 ──

const TagManagement: React.FC = () => {
  const [tree, setTree] = useState<TagNode[]>(() => cloneTree(mockTagTree));
  const [msg, ctx] = antMsg.useMessage();
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const [descEditId, setDescEditId] = useState<string | null>(null);
  const [descEditValue, setDescEditValue] = useState('');
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [addModalOpen, setAddModalOpen] = useState(false);
  const [addModalName, setAddModalName] = useState('');
  const [addModalParentId, setAddModalParentId] = useState<string | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null);
  const addInputRef = React.useRef<React.ComponentRef<typeof Input>>(null);
  const editRef = React.useRef<HTMLInputElement>(null);

  const [loading, setLoading] = useState(true);

  // 递归将 mock 标签树种子数据写入数据库
  async function seedTags(nodes: TagNode[], parentId?: string): Promise<void> {
    for (const node of nodes) {
      const row = await tagService.create({
        name: node.name,
        parent_id: parentId || null,
        description: node.description || '',
      });
      if (node.children && node.children.length > 0) {
        await seedTags(node.children, row.id);
      }
    }
  }

  // 挂载时从 API 加载标签树，失败则回退到 mock 数据
  useEffect(() => {
    (async () => {
      try {
        const data = await tagService.getTree();
        if (data && data.length > 0) {
          setTree(data);
        } else {
          // 数据库标签表为空，写入 mock 种子数据
          await seedTags(mockTagTree);
          const seeded = await tagService.getTree();
          if (seeded && seeded.length > 0) setTree(seeded);
        }
      } catch {
        msg.warning('标签数据加载失败，使用本地数据');
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const flatRows = flattenTree(tree);
  const expandView: 'expand' | 'collapse' = expandedIds.size >= flatRows.length ? 'expand' : 'collapse';
  // Only show expanded rows
  const visibleRows = flatRows.filter((row, index) => {
    if (row.level === 0) return true;
    let ancestorLevel = row.level - 1;
    for (let i = index - 1; i >= 0; i--) {
      if (flatRows[i].level === ancestorLevel) {
        if (!expandedIds.has(flatRows[i].node.id)) return false;
        ancestorLevel--;
        if (ancestorLevel < 0) break;
      }
    }
    return true;
  });

  const startEditing = (id: string, currentName: string) => {
    setEditingId(id);
    setEditValue(currentName);
    setTimeout(() => editRef.current?.focus(), 50);
  };

  const saveEdit = () => {
    const id = editingId;
    const newName = editValue.trim();
    if (!id || !newName) { setEditingId(null); return; }
    // 乐观更新本地状态
    setTree(prev => {
      const t = cloneTree(prev);
      const path = findPath(t, id);
      if (!path) return prev;
      const node = getNodeByPath(t, path);
      if (node) node.name = newName;
      return t;
    });
    setEditingId(null);
    // 持久化到后端
    tagService.update(id, { name: newName }).then(
      () => msg.success('标签已重命名'),
      () => msg.error('重命名失败，请重试')
    );
  };

  const saveDesc = () => {
    const id = descEditId;
    if (!id) return;
    const newDesc = descEditValue.trim() || undefined;
    setTree(prev => {
      const t = cloneTree(prev);
      const path = findPath(t, id);
      if (!path) return prev;
      const node = getNodeByPath(t, path);
      if (node) node.description = newDesc;
      return t;
    });
    setDescEditId(null);
    // 持久化
    tagService.update(id, { description: newDesc || '' }).then(
      () => {},
      () => msg.error('保存说明失败')
    );
  };

  // Level colors
  const LEVEL_COLORS = [COLORS.labelDark, COLORS.primary, COLORS.purple, '#008080', COLORS.amber];
  const LEVEL_BG = ['#e8ecf0', '#e0ecfa', '#ede6f5', '#dceeea', '#f5ede4'];

  const toggleExpand = (id: string) => {
    setExpandedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const addChild = (parentId: string | null, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setAddModalParentId(parentId);
    setAddModalName('');
    setAddModalOpen(true);
    setTimeout(() => addInputRef.current?.focus(), 50);
  };

  const confirmAdd = () => {
    const name = addModalName.trim();
    if (!name) { msg.warning('请输入标签名称'); return; }
    // 调用 API 创建（获取服务端生成的 ID）
    tagService.create({ name, parent_id: addModalParentId }).then(
      (row) => {
        const newId = row.id;
        setTree(prev => {
          const t = cloneTree(prev);
          if (!addModalParentId) {
            t.push({ id: newId, name });
          } else {
            const path = findPath(t, addModalParentId);
            if (!path) return prev;
            const parent = getNodeByPath(t, path);
            if (parent) {
              if (!parent.children) parent.children = [];
              parent.children.push({ id: newId, name });
            }
          }
          return t;
        });
        if (addModalParentId) setExpandedIds(prev => new Set(prev).add(addModalParentId!));
        setAddModalOpen(false);
        msg.success('已添加标签');
      },
      () => {
        // API 不可用，降级为本地纯内存操作
        const newId = uid();
        setTree(prev => {
          const t = cloneTree(prev);
          if (!addModalParentId) {
            t.push({ id: newId, name });
          } else {
            const path = findPath(t, addModalParentId);
            if (!path) return prev;
            const parent = getNodeByPath(t, path);
            if (parent) {
              if (!parent.children) parent.children = [];
              parent.children.push({ id: newId, name });
            }
          }
          return t;
        });
        if (addModalParentId) setExpandedIds(prev => new Set(prev).add(addModalParentId!));
        setAddModalOpen(false);
        msg.warning('已添加（本地模式，刷新后丢失）');
      }
    );
  };

  const deleteNode = (id: string) => {
    const path = findPath(tree, id);
    if (!path) return;
    const node = getNodeByPath(tree, path);
    if (node) setDeleteTarget({ id, name: node.name });
  };

  const confirmDelete = () => {
    const target = deleteTarget;
    if (!target) return;
    const removedEditing = editingId === target.id;
    // 乐观更新本地状态
    setTree(prev => {
      const t = cloneTree(prev);
      const p = findPath(t, target.id);
      if (!p) return prev;
      if (p.length === 1) {
        t.splice(p[0], 1);
      } else {
        const parentPath = p.slice(0, -1);
        const parent = getNodeByPath(t, parentPath);
        if (parent?.children) parent.children.splice(p[p.length - 1], 1);
      }
      return t;
    });
    if (removedEditing) setEditingId(null);
    setDeleteTarget(null);
    msg.success('已删除');
    // 持久化到后端
    tagService.delete(target.id).then(
      () => {},
      () => msg.error('删除失败，请重试')
    );
  };

  const moveNode = (id: string, direction: -1 | 1, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    let movedId: string | undefined;
    let swappedId: string | undefined;
    setTree(prev => {
      const t = cloneTree(prev);
      const path = findPath(t, id);
      if (!path) return prev;
      const idx = path[path.length - 1];
      const newIdx = idx + direction;
      if (newIdx < 0) return prev;
      if (path.length === 1) {
        if (newIdx >= t.length) return prev;
        swappedId = t[newIdx].id;
        [t[idx], t[newIdx]] = [t[newIdx], t[idx]];
      } else {
        const parentPath = path.slice(0, -1);
        const parent = getNodeByPath(t, parentPath);
        if (!parent?.children || newIdx >= parent.children.length) return prev;
        swappedId = parent.children[newIdx].id;
        [parent.children[idx], parent.children[newIdx]] = [parent.children[newIdx], parent.children[idx]];
      }
      movedId = id;
      return t;
    });
    // 持久化排序（更新两个被交换节点的 sort_order）
    if (movedId && swappedId) {
      const now = Date.now();
      if (direction > 0) {
        // 下移：movedId 获得更大 sort_order（排在 swappedId 之后）
        tagService.update(movedId, { sort_order: now }).then(
          () => tagService.update(swappedId!, { sort_order: now - 1 }),
          () => {}
        ).catch(() => {});
      } else {
        // 上移：movedId 获得更小 sort_order（排在 swappedId 之前）
        tagService.update(movedId, { sort_order: now - 1 }).then(
          () => tagService.update(swappedId!, { sort_order: now }),
          () => {}
        ).catch(() => {});
      }
    }
  };

  // ── 渲染表格 ──


  return (
    <div>
      {ctx}
      {loading && tree.length === 0 ? (
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 200 }}>
          <Spin tip="加载标签数据..." />
        </div>
      ) : (
      <>
      <div style={{ marginBottom: 4 }}>
        <span style={{ fontSize: 17, fontWeight: 700, color: COLORS.textDark }}>标签管理</span>
      </div>

      <div style={{ width: '100%', maxWidth: 1050, display: 'flex', gap: 20, alignItems: 'flex-start', paddingTop: 20 }}>
        {/* 左侧：标签表格 */}
        <div style={{ flex: 1 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
            <div style={{ display: 'flex', gap: 0, borderBottom: `2px solid ${COLORS.border}` }}>
              <div onClick={() => {
                const all: string[] = [];
                const walk = (ns: TagNode[]) => ns.forEach(n => { all.push(n.id); if (n.children) walk(n.children); });
                walk(tree);
                setExpandedIds(new Set(all));
              }} style={{
                padding: '8px 20px', cursor: 'pointer', fontSize: 14,
                borderBottom: expandView === 'expand' ? `2px solid ${COLORS.primary}` : '2px solid transparent',
                color: expandView === 'expand' ? COLORS.primary : COLORS.textSecondary,
                fontWeight: expandView === 'expand' ? 600 : 400,
                marginBottom: -2, transition: 'all 0.15s',
              }}>全部展开</div>
              <div onClick={() => {
                setExpandedIds(new Set());
              }} style={{
                padding: '8px 20px', cursor: 'pointer', fontSize: 14,
                borderBottom: expandView === 'collapse' ? `2px solid ${COLORS.primary}` : '2px solid transparent',
                color: expandView === 'collapse' ? COLORS.primary : COLORS.textSecondary,
                fontWeight: expandView === 'collapse' ? 600 : 400,
                marginBottom: -2, transition: 'all 0.15s',
              }}>全部折叠</div>
            </div>
            <Button type="default" ghost icon={<PlusOutlined />}
              onClick={() => addChild(null)}
              style={{
                borderRadius: 8, border: `1.5px dashed ${COLORS.borderLight}`,
                color: COLORS.primary, fontSize: 13, fontWeight: 600, height: 32,
                transition: 'all 0.2s',
              }}
              onMouseEnter={e => { e.currentTarget.style.border = `1.5px dashed ${COLORS.primary}`; e.currentTarget.style.background = COLORS.bgSelected; }}
              onMouseLeave={e => { e.currentTarget.style.border = `1.5px dashed ${COLORS.borderLight}`; e.currentTarget.style.background = 'transparent'; }}
            >新增一级标签</Button>
          </div>
          <div style={{ border: `1px solid ${COLORS.borderCard}`, borderRadius: 6, overflow: 'auto', boxShadow: '0 1px 3px rgba(0,0,0,0.04)' }}>
          <table style={{ width: '100%', minWidth: 600, borderCollapse: 'collapse', tableLayout: 'fixed' }}>
            <colgroup>
              <col style={{ width: 36 }} />
              <col />
              <col style={{ width: 56 }} />
              <col style={{ width: 180 }} />
              <col style={{ width: 500 }} />
            </colgroup>
            <thead>
              <tr style={{ background: '#f0f4ff' }}>
                <th style={{ width: 36, minWidth: 36, maxWidth: 36, padding: '10px 4px', fontSize: 11, fontWeight: 600, color: '#2c3e6b', textAlign: 'center', letterSpacing: 0.5, borderBottom: '2px solid #d6e0f0' }} />
                <th style={{ padding: '10px 4px', fontSize: 11, fontWeight: 600, color: '#2c3e6b', textAlign: 'left', letterSpacing: 0.5, borderBottom: '2px solid #d6e0f0' }}>标签名称</th>
                <th style={{ width: 56, minWidth: 56, maxWidth: 56, padding: '10px 4px', fontSize: 11, fontWeight: 600, color: '#2c3e6b', textAlign: 'center', letterSpacing: 0.5, borderBottom: '2px solid #d6e0f0', borderLeft: `1px solid ${COLORS.borderInner}`, borderRight: `1px solid ${COLORS.borderInner}` }}>子级</th>
                <th style={{ width: 236, minWidth: 236, maxWidth: 236, padding: '10px 4px', fontSize: 11, fontWeight: 600, color: '#2c3e6b', textAlign: 'center', letterSpacing: 0.5, borderBottom: '2px solid #d6e0f0' }}>操作</th>
                <th style={{ width: 500, minWidth: 500, maxWidth: 500, padding: '10px 4px', fontSize: 11, fontWeight: 600, color: '#2c3e6b', textAlign: 'left', letterSpacing: 0.5, borderBottom: '2px solid #d6e0f0', borderLeft: `1px solid ${COLORS.borderInner}`, background: '#f0f4ff' }}>说明</th>
              </tr>
            </thead>
            <tbody>
              {visibleRows.length === 0 ? (
                <tr><td colSpan={5} style={{ padding: 32, textAlign: 'center', color: COLORS.textDisabled, fontSize: 13 }}>暂无标签，点击右上角「新增一级标签」开始</td></tr>
              ) : visibleRows.map(({ node, level, connector }) => {
                const isEditing = editingId === node.id;
                const hasChildren = node.children && node.children.length > 0;
                const isExpanded = expandedIds.has(node.id);
                const lc = LEVEL_COLORS[Math.min(level, 4)];
                const lbg = LEVEL_BG[Math.min(level, 4)];
                return (
                  <tr key={node.id}
                    style={{
                      cursor: 'pointer',
                      background: isEditing ? '#f0f6ff' : '#fff',
                      transition: 'background 0.12s',
                      borderBottom: `1px solid ${COLORS.borderInner}`,
                      height: 44, minHeight: 44, lineHeight: '18px',
                    }}
                    onMouseEnter={e => { if (!isEditing) e.currentTarget.style.background = '#f8faff'; }}
                    onMouseLeave={e => { if (!isEditing) e.currentTarget.style.background = '#fff'; }}
                  >
                    <td style={{ width: 36, minWidth: 36, maxWidth: 36, padding: '2px 2px', textAlign: 'center', verticalAlign: 'middle' }}>
                      {hasChildren ? (
                        <span onClick={e => { e.stopPropagation(); toggleExpand(node.id); }}
                          style={{ cursor: 'pointer', fontSize: 13, color: lc, display: 'inline-block', userSelect: 'none' }}>
                          {isExpanded ? '−' : '+'}
                        </span>
                      ) : (
                        <span style={{ display: 'inline-block', width: 13 }} />
                      )}
                    </td>
                    <td style={{ padding: '2px 4px', verticalAlign: 'middle' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6, cursor: 'text' }}
                        onClick={() => { if (!isEditing) startEditing(node.id, node.name); }}>
                        {level > 0 && (
                          <div style={{ display: 'flex', alignItems: 'stretch', flexShrink: 0, height: 14 }}>
                            {Array.from({ length: level }).map((_, li) => (
                              <div key={li} style={{ width: 22, position: 'relative' }}>
                                {!connector[li] && (
                                  <div style={{ position: 'absolute', left: 10, top: 0, bottom: 0, width: 1, background: '#d4dce8', transform: 'scaleX(0.5)', transformOrigin: 'left top' }} />
                                )}
                                {li === level - 1 && (
                                  <div style={{ position: 'absolute', left: 10, top: '50%', right: 0, height: 1, background: '#d4dce8', transform: 'scaleY(0.5)', transformOrigin: 'left top' }} />
                                )}
                              </div>
                            ))}
                          </div>
                        )}
                        <div style={{
                          width: 16, height: 16, borderRadius: 3, flexShrink: 0,
                          background: lbg, color: lc,
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                          fontSize: 10, fontWeight: 700, fontFamily: 'monospace',
                          border: isEditing ? '1.5px solid ' + lc : '1.5px solid transparent',
                        }}>
                          {level + 1}
                        </div>
                        {isEditing ? (
                          <input ref={editRef}
                            value={editValue}
                            onChange={e => setEditValue(e.target.value)}
                            onBlur={saveEdit}
                            onKeyDown={e => { if (e.key === 'Enter') saveEdit(); if (e.key === 'Escape') setEditingId(null); }}
                            onClick={e => e.stopPropagation()}
                            style={{
                              flex: 1, border: `1px solid ${COLORS.primary}`, borderRadius: 3,
                              padding: '1px 4px', fontSize: 12, outline: 'none',
                              fontFamily: 'inherit', background: '#fff',
                            }}
                          />
                        ) : (
                          <span style={{
                            color: lc,
