  /** 保存项目版本 */
  saveVersion: (projectId: string, data: Partial<ProjectVersion>) =>
    api.post<ProjectVersion>(`/project-versions`, { ...data, project_id: projectId }),

  /** 保存组和明细 */
  saveGroup: (projectId: string, versionId: string, data: any) =>
