import type { Group } from '../types';
import { projectService } from '../services/projectService';
import { toCamel } from './api';

/** 格式化数字为千单位显示（如 1234 → "1K"） */
export const fmtK = (v: number) => Math.round(v / 1000).toLocaleString() + 'K';

/** 财年选项列表 */
export const FY_OPTIONS = ['FY2425', 'FY2526', 'FY2627'] as const;

// 缓存已加载的项目数据，避免重复请求
const projectCache = new Map<string, { groups: Group[]; version?: { warrantyRate: number; riskRate: number } }>();

/**
 * 预加载报价数据到缓存（供同步 loadQuotationGroups 使用）
 * 流程：报价ID → 查 quotation → 取 project_id → 加载项目完整数据
 */
export async function preloadQuotationGroups(quotationId: string): Promise<void> {
  if (projectCache.has(quotationId)) return;
  try {
    // 1. 先查报价获取 project_id + version_no
    const token = localStorage.getItem('budget_token');
    const quoteResp = await fetch(`/api/v1/quotations/${quotationId}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!quoteResp.ok) throw new Error('报价不存在');
    const quote = toCamel(await quoteResp.json());
    const projectId = quote.projectId;
    if (!projectId) throw new Error('报价缺少 project_id');
    const quoteVerNo = quote.versionNo || '';

    // 2. 再加载项目完整数据
    const project = await projectService.getFull(projectId);
    // ⚠️ 按版本过滤组数据，避免加载全量组导致成本对比表重复显示多条设备组
    const version = project.versions?.find((v: any) => v.versionNo === quoteVerNo) || project.versions?.[0];
    const versionId = version?.id || '';
    const versionGroups = (project.groups || []).filter((g: any) =>
      g.versionId === versionId
    );
    // 版本过滤未命中时回退全量组（兼容旧数据），避免成本对比表空白
    const finalGroups = versionGroups.length > 0 ? versionGroups : (project.groups || []);
    projectCache.set(quotationId, {
      groups: finalGroups.map((g: any) => ({
        ...g,
        items: (g.items || []).map((i: any) => ({ ...i })),
      })),
      version: version ? {
        warrantyRate: version.warrantyRate ?? 0,
        riskRate: version.riskRate ?? 0,
      } : undefined,
    });
  } catch {
    projectCache.set(quotationId, { groups: [], version: undefined });
  }
}

/**
 * 从缓存同步获取报价编制数据（保持与原有同步接口兼容）
 */
export function loadQuotationGroups(quotationId: string): {
  groups: Group[];
  version?: { warrantyRate: number; riskRate: number };
} {
  return projectCache.get(quotationId) || { groups: [], version: undefined };
}

/** 批量预加载 */
export async function preloadQuotationGroupsBatch(ids: string[]): Promise<void> {
  await Promise.all(ids.map(id => preloadQuotationGroups(id)));
}

/** 清除项目缓存（用于重新加载） */
export function clearQuotationCache() { projectCache.clear(); }

/**
 * API 基础客户端 - 封装 fetch，统一处理错误、环境配置
 *
 * 命名规范边界：这是前后端 camelCase/snake_case 的转换层。
 * GET 响应自动 toCamel() 转驼峰，POST/PUT body 自动 toSnake() 转蛇形。
 * 所有 API 通信必须走此客户端，禁止直接 fetch()。
 * 详见 memory/naming-convention-standard.md
 */

const API_BASE = import.meta.env.VITE_API_BASE || '/api/v1';

// ── GET 请求缓存（30 秒 TTL，避免页面切换重复请求） ──
const cache = new Map<string, { data: any; expiry: number }>();
const CACHE_TTL = 30_000;

function getCached(key: string): any | undefined {
  const entry = cache.get(key);
  if (entry && entry.expiry > Date.now()) return entry.data;
  cache.delete(key);
  return undefined;
}

function setCache(key: string, data: any) {
  cache.set(key, { data, expiry: Date.now() + CACHE_TTL });
  if (cache.size > 100) {
    const firstKey = cache.keys().next().value;
    if (firstKey) cache.delete(firstKey);
  }
}

/** 将响应数据所有键从蛇形转换为驼峰（后端 snake_case → 前端 camelCase） */
export function toCamel(obj: any): any {
  if (obj === null || obj === undefined) return obj;
  if (typeof obj !== 'object') return obj;
  if (obj instanceof Date) return obj;
  if (Array.isArray(obj)) return obj.map(toCamel);
  const result: Record<string, any> = {};
  for (const key of Object.keys(obj)) {
    result[key.replace(/_([a-z])/g, (_, l) => l.toUpperCase())] = toCamel(obj[key]);
  }
  return result;
}

/** 将请求数据所有键从驼峰转换为蛇形（前端 camelCase → 后端 snake_case） */
export function toSnake(obj: Record<string, any>): Record<string, any> {
  const result: Record<string, any> = {};
  for (const key of Object.keys(obj)) {
    result[key.replace(/[A-Z]/g, l => '_' + l.toLowerCase())] = obj[key];
  }
  return result;
}

export class ApiError extends Error {
  status: number;

  constructor(status: number, message: string) {
    super(message);
    this.status = status;
    this.name = 'ApiError';
  }
}

/** 从 localStorage 获取 JWT token */
function getToken(): string | null {
  try { return localStorage.getItem('budget_token'); } catch { return null; }
}

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const url = `${API_BASE}${path}`;
  const cacheKey = options?.method ? path : path;

  // GET 请求优先走缓存
  if (!options || options.method === undefined || options.method === 'GET') {
    const cached = getCached(cacheKey);
    if (cached !== undefined) return cached as T;
  }

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const token = getToken();
  if (token) headers['Authorization'] = `Bearer ${token}`;

  const res = await fetch(url, {
    method: options?.method,
    body: options?.body,
    headers: { ...headers, ...(options?.headers as Record<string, string> || {}) },
    // 非 GET 请求启用 keepalive：确保页面卸载前请求完成（解决 onBlur 后立即刷新的问题）
    keepalive: options?.method && options.method !== 'GET' ? true : undefined,
  });

  // 401 token 过期 → 清除登录状态并跳转
  if (res.status === 401) {
    localStorage.removeItem('budget_token');
    window.location.href = '/budget/login';
    throw new ApiError(401, '登录已过期，请重新登录');
  }

  if (!res.ok) {
    const body = await res.json().catch(() => ({ error: res.statusText }));
    throw new ApiError(res.status, body.error || `Request failed (${res.status})`);
  }

  // 204 No Content
  if (res.status === 204) return undefined as T;

  const data = await res.json();
  const result = toCamel(data) as T;

  // GET 请求写入缓存
  if (!options || options.method === undefined || options.method === 'GET') {
    setCache(cacheKey, result);
  } else {
    // 非 GET 请求（POST/PUT/DELETE）清除相关前缀缓存
    const resourcePrefix = path.split('/')[1] || path.split('/')[0] || '';
    clearCache('/' + resourcePrefix);
  }

  return result;
}

/** 清除缓存（用于数据变更后强制刷新） */
export function clearCache(resourcePrefix?: string) {
  if (resourcePrefix) {
    for (const key of cache.keys()) {
      if (key.startsWith(resourcePrefix)) cache.delete(key);
    }
  } else {
    cache.clear();
  }
}

export const api = {
  get: <T>(path: string) => request<T>(path),
  post: <T>(path: string, body: unknown) =>
    request<T>(path, { method: 'POST', body: JSON.stringify(body) }),
  put: <T>(path: string, body: unknown) =>
    request<T>(path, { method: 'PUT', body: JSON.stringify(body) }),
  delete: <T>(path: string) =>
    request<T>(path, { method: 'DELETE' }),
};

/* ---- 通用 CRUD 服务 ---- */

/** 通用列表/详情查询 */
export async function fetchList<T>(resource: string, params?: Record<string, string>): Promise<T[]> {
  const qs = params ? '?' + new URLSearchParams(params).toString() : '';
  return api.get<T[]>(`/${resource}${qs}`);
}

export async function fetchById<T>(resource: string, id: string): Promise<T> {
  return api.get<T>(`/${resource}/${id}`);
}

export async function createItem<T>(resource: string, data: Partial<T>): Promise<T> {
  return api.post<T>(`/${resource}`, data);
}

export async function updateItem<T>(resource: string, id: string, data: Partial<T>): Promise<T> {
  return api.put<T>(`/${resource}/${id}`, data);
}

export async function deleteItem(resource: string, id: string): Promise<void> {
  await api.delete(`/${resource}/${id}`);
}

